/* ============================================================
   CARD LANE BATTLE — Professional TCG Theme
   ============================================================ */
:root {
  /* Tron palette — sleek neon cyan used for panel chrome + focus states.
     Kept deliberately narrow: semantic colors (green=player, red=AI,
     gold=energy) are untouched so the UI still reads at a glance. */
  --tron:       #4fc3f7;           /* primary cyan (edges, labels) */
  --tron-dim:   rgba(79,195,247,0.28);  /* standard 1px border */
  --tron-edge:  rgba(79,195,247,0.55);  /* hover / active border */
  --tron-glow:  rgba(79,195,247,0.22);  /* ambient outer glow */
  --tron-ink:   rgba(79,195,247,0.08);  /* fill wash for subtle bg */

  /* Keyword palette — single source of truth for trait / debuff / mechanic
     colors. Badge colors (.status-badge.badge-*) are canonical; description
     spans (.kw-*) reference the same vars so changing a color here updates
     BOTH the under-name pill and the in-text keyword in one place.

     HARMONIZED to the 5-color palette (Blue / Red / Gold / Green / Silver).
     Previously-off-palette colors (purple, orange, teal, pink variants)
     have been remapped into the nearest semantic tier so every neon
     element in the game reads from the same five families. */
  --palette-blue:    #7fd0ff;  /* light blue */
  --palette-red:     #ff8a7a;  /* light red */
  --palette-gold:    #ffe066;  /* light gold */
  --palette-green:   #7ee8a5;  /* light green */
  --palette-silver:  #e8eef6;  /* light silver */

  /* Palette now includes purple (for tricks + control-themed keywords).
     Every keyword maps to one of: blue / red / gold / green / silver / purple. */
  --palette-purple:  #d7b3e6;  /* light purple */

  /* Traits (match existing .badge-*) */
  --kw-evade:          #7ee8a5;   /* green */
  --kw-armor:          #ffe066;   /* gold */
  --kw-bullseye:       #ff8a7a;   /* red */
  --kw-overdrive:      #ff8a7a;   /* red */
  --kw-splash:         #ff8a7a;   /* red */
  --kw-immune:         #ffe066;   /* gold */
  --kw-invincible:     #e8eef6;   /* silver */
  --kw-unresistible:   #d7b3e6;   /* purple */
  --kw-taunt:          #ffe066;   /* gold */
  --kw-hunt:           #ff8a7a;   /* red */
  --kw-revive:         #d7b3e6;   /* purple — distinct from --kw-evade green so a Wolverine REVIVE 1 badge can't be misread as EVADE 1 (user feedback). Purple also reads as "supernatural / cheat-death" which fits the resurrection mechanic semantically. */
  --kw-dmg-immune:     #d7b3e6;   /* purple */
  --kw-untrickable:    #e8eef6;   /* silver */
  --kw-mind-ctrl:      #ffe066;   /* gold */
  --kw-drain:          #ff8a7a;   /* red */
  --kw-stun:           #ffe066;   /* gold */
  --kw-freeze:         #7fd0ff;   /* blue */
  --kw-fear:           #e8eef6;   /* silver */
  --kw-burn:           #ff7a00;   /* orange */
  --kw-charm:          #d7b3e6;   /* purple */
  --kw-energy:         #ffe066;   /* gold */
  /* New mechanic verbs */
  --kw-summon:         #7ee8a5;   /* green */
  --kw-block:          #7fd0ff;   /* blue */
  --kw-jump:           #ff8a7a;   /* red */
  --kw-destroy:        #ff8a7a;   /* red */
  --kw-sacrifice:      #d7b3e6;   /* purple */
  --kw-draw:           #7fd0ff;   /* blue */
  --kw-chain:          #ffe066;   /* gold */
  --kw-peek:           #7fd0ff;   /* blue */
  --kw-devour:         #d7b3e6;   /* purple */
  --kw-absorb:         #7ee8a5;   /* green */
  --kw-regain:         #7ee8a5;   /* green */
  --kw-convert:        #ffe066;   /* gold */
  /* Infinity Stones — mapped to 6-color palette. */
  --kw-stone-space:    #7fd0ff;   /* blue */
  --kw-stone-time:     #7ee8a5;   /* green */
  --kw-stone-power:    #d7b3e6;   /* purple */
  --kw-stone-soul:     #ff8a7a;   /* red */
  --kw-stone-mind:     #ffe066;   /* gold */
  --kw-stone-reality:  #ff8a7a;   /* red */
  /* Stat-orb face tints for inline (+N/+N) callouts (matches .stat-atk
     / .stat-hp color values in CSS). */
  --kw-stat-atk:       #7ee8a5;
  --kw-stat-hp:        #f1948a;

  /* ============================================================
     DESIGN SYSTEM TOKENS (polish-pass Tier 1)
     ============================================================
     Standardized scales for type, spacing, glow intensity, and
     interactive state animation. Defined here so any rule can
     read `var(--type-body)` / `var(--space-md)` etc. and the
     whole UI stays in rhythm.

     Migration policy: NEW rules use these vars; existing rules
     migrate opportunistically when touched. We don't audit-and-
     replace 14k lines in one pass.
     ============================================================ */

  /* ----- Type scale -----
     Six tiers covering everything from microcopy to hero titles.
     Sizes hit a clean major-second ratio (~1.125) up to body, then
     wider 1.25-1.5 jumps for hierarchy at the heading tiers. Line
     heights at the 1.4-1.5 range per typography-research consensus. */
  --type-caption:     10px;   /* timestamps, kbd hints, microcopy */
  --type-caption-lh:  1.40;
  --type-body:        12px;   /* default UI copy, badges, pills */
  --type-body-lh:     1.45;
  --type-sub:         13px;   /* sub-labels, button sub-text */
  --type-sub-lh:      1.40;
  --type-label:       14px;   /* primary labels, tab labels */
  --type-label-lh:    1.30;
  --type-heading:     18px;   /* panel titles, modal headings */
  --type-heading-lh:  1.30;
  --type-hero:        32px;   /* hero text — main menu title only */
  --type-hero-lh:     1.10;

  /* ----- Spacing scale -----
     8/12/16/24/32/48 base rhythm. Use consistently across padding,
     margin, and gap. Avoids the "every component picks its own
     padding" amateur tell. */
  --space-xs:   4px;
  --space-sm:   8px;
  --space-md:   12px;
  --space-lg:   16px;
  --space-xl:   24px;
  --space-2xl:  32px;
  --space-3xl:  48px;

  /* ----- Glow tier system -----
     Three intensity levels. Reserve `focal` for elements that
     need MAX attention right now (active player's HUD, selected
     card, current phase indicator). Demoting ambient elements to
     `subtle` lets the focal pop.

     All three pull from --theme-rgb so the active Neon Theme
     drives them. Each tier composes outer glow + a faint inset
     ring for depth. */
  --glow-subtle:
    0 0 6px  rgba(var(--theme-rgb, 79,195,247), 0.18),
    0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.08);
  --glow-standard:
    0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.35),
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.14),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.10);
  --glow-focal:
    0 0 16px rgba(var(--theme-rgb, 79,195,247), 0.65),
    0 0 36px rgba(var(--theme-rgb, 79,195,247), 0.28),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.30);

  /* ----- Interactive state ramps -----
     Universal hover / press / click contract. Buttons that want
     the standard feel pull `transition: var(--ix-transition)`
     and apply the hover/active transforms below. */
  --ix-transition:
    background 140ms cubic-bezier(0.2, 0, 0, 1),
    border-color 140ms cubic-bezier(0.2, 0, 0, 1),
    box-shadow 140ms cubic-bezier(0.2, 0, 0, 1),
    transform 90ms cubic-bezier(0.2, 0, 0, 1);
  --ix-hover-translate:  translateY(-1px);
  --ix-active-translate: translateY(1px);
}

/* ---- Keyword span — generic base style + per-keyword color via var ----
   Rendered by ui.js formatDesc() for every recognized ability/mechanic in
   card and trick description text. Bold + neon text-shadow so the term pops
   against the dark desc background. */
.kw {
  font-weight: 700;
  /* Keyword highlights match the bold-label size — one "highlight
     tier" sitting just above the body. Body 8.5 px, kw 10 px. */
  font-size: 10px;
  text-shadow: 0 0 6px currentColor, 0 1px 2px rgba(0,0,0,0.85);
}
/* Tooltipable body keywords — when a `.kw` span carries `data-kw` it's
   interactive (hover for tooltip, click to pin). Cursor + a subtle
   text-shadow lift on hover signals interactivity without redoing the
   whole pill chrome. Status badges with data-kw inherit via the same
   selector since they also stamp the attribute. */
.kw[data-kw],
.status-badge[data-kw] {
  cursor: help;
  transition: text-shadow 0.15s ease, filter 0.15s ease;
}
.kw[data-kw]:hover,
.status-badge[data-kw]:hover {
  text-shadow: 0 0 10px currentColor, 0 1px 2px rgba(0,0,0,0.85);
  filter: brightness(1.2);
}
.kw-evade        { color: var(--kw-evade); }
.kw-armor        { color: var(--kw-armor); }
.kw-bullseye     { color: var(--kw-bullseye); }
.kw-overdrive    { color: var(--kw-overdrive); }
.kw-splash       { color: var(--kw-splash); }
.kw-immune       { color: var(--kw-immune); }
.kw-invincible   { color: var(--kw-invincible); }
.kw-unresistible { color: var(--kw-unresistible); }
.kw-taunt        { color: var(--kw-taunt); }
.kw-hunt         { color: var(--kw-hunt); }
.kw-revive       { color: var(--kw-revive); }
.kw-dmg-immune   { color: var(--kw-dmg-immune); }
.kw-untrickable  { color: var(--kw-untrickable); }
.kw-mind-ctrl    { color: var(--kw-mind-ctrl); }
.kw-drain        { color: var(--kw-drain); }
.kw-stun         { color: var(--kw-stun); }
.kw-freeze       { color: var(--kw-freeze); }
/* Fear keeps its inky look — dark color + white halo, distinct from other kws */
.kw-fear         { color: var(--kw-fear); text-shadow: 0 0 6px rgba(255,255,255,0.55), 0 1px 2px rgba(0,0,0,0.85); }
.kw-charm        { color: var(--kw-charm); }
.kw-energy       { color: var(--kw-energy); }
.kw-summon       { color: var(--kw-summon); }
.kw-block        { color: var(--kw-block); }
.kw-jump         { color: var(--kw-jump); }
.kw-destroy      { color: var(--kw-destroy); }
.kw-sacrifice    { color: var(--kw-sacrifice); }
.kw-draw         { color: var(--kw-draw); }
.kw-chain        { color: var(--kw-chain); }
.kw-peek         { color: var(--kw-peek); }
.kw-devour       { color: var(--kw-devour); }
.kw-absorb       { color: var(--kw-absorb); }
.kw-regain       { color: var(--kw-regain); }
.kw-convert      { color: var(--kw-convert); }
.kw-stone-space   { color: var(--kw-stone-space); }
.kw-stone-time    { color: var(--kw-stone-time); }
.kw-stone-power   { color: var(--kw-stone-power); }
.kw-stone-soul    { color: var(--kw-stone-soul); }
.kw-stone-mind    { color: var(--kw-stone-mind); }
.kw-stone-reality { color: var(--kw-stone-reality); }

/* Inside a trigger label (<b> in desc), keyword spans defer to the label's
   own color + glow so "When Destroyed:" reads as one unified neon label
   instead of half-green half-red. Selector specificity (0,2,1) beats the
   plain .kw-* rules (0,1,0). */
.card-desc b .kw,
.trick-desc b .kw,
.dead-pile-card .card-desc b .kw,
.choice-tray .card-desc b .kw {
  color: inherit !important;
  text-shadow: inherit;
}

/* ---- Stat-number pops — mirror the orb glow ----
   Emitted by formatDesc() for (+N/+N) and bare N/N patterns. The text-shadow
   stack mimics the .stat-atk / .stat-hp box-shadow: a tight inner glow + a
   wider bloom. Same rgba() bases (46,204,113 and 231,76,60) as the orbs so
   the number in desc reads as the same neon as the orb next to it. */
.stat-num {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.stat-num-atk {
  color: var(--kw-stat-atk);
  text-shadow:
    0 0 4px rgba(46,204,113,0.95),
    0 0 10px rgba(46,204,113,0.70),
    0 0 18px rgba(46,204,113,0.35),
    0 1px 2px rgba(0,0,0,0.85);
}
.stat-num-hp {
  color: var(--kw-stat-hp);
  text-shadow:
    0 0 4px rgba(231,76,60,0.95),
    0 0 10px rgba(231,76,60,0.75),
    0 0 18px rgba(231,76,60,0.40),
    0 1px 2px rgba(0,0,0,0.85);
}
* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  background: #000000;
  color: #e0e0e0;
  font-family: 'Inter', 'Segoe UI', system-ui, sans-serif;
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  /* Container context so the @container (max-width: ...) rules below
     fire either when body's actual width is phone-sized OR when the
     "Mobile preview" toggle constrains body to 390px on a desktop
     viewport. Avoids needing duplicate CSS for the toggled state. */
  container-type: inline-size;
}

/* ============================================================
   VIEWPORT TOGGLE — desktop "Mobile preview" mode
   ============================================================
   When body has class .preview-mobile, constrain its width to a
   phone shape and center it inside the viewport. The page then
   acts exactly as if it were running on a 390x844 phone (the
   @container rules above kick in automatically). The surrounding
   viewport gets a darker wash + a thin neon ring to read as
   "phone chrome" so the user can see they're in preview mode.
   ============================================================ */
body.preview-mobile {
  /* Use the html element as the dark backdrop; body becomes the
     phone-shaped frame floated inside it. */
  width: 390px;
  min-height: 844px;
  margin: 24px auto;
  border: 1px solid var(--tron-edge);
  border-radius: 28px;
  box-shadow:
    0 0 0 6px #0a0d11,                 /* phone bezel ring */
    0 0 24px rgba(79,195,247,0.18),    /* soft cyan halo */
    0 12px 48px rgba(0,0,0,0.55);
  overflow: hidden;
  position: relative;
  /* CRITICAL: makes <body> a containing block for `position: fixed`
     descendants. Without this, the menu/draft/encyclopedia/settings
     overlays still cover the full viewport (1022px) even though body
     is 390px. The `transform` is what triggers it (any non-none
     transform on an ancestor establishes a containing block for fixed
     descendants per the CSS positioning spec). `translateZ(0)` is the
     idiomatic no-op transform for exactly this purpose. */
  transform: translateZ(0);
}
/* Bump the toggle button outside the phone frame (it's a fixed
   position element so it ALSO gets contained by the transform — pull
   it back to the actual viewport edge by re-positioning it against
   the html element). */
body.preview-mobile ~ .viewport-toggle,
body.preview-mobile + .viewport-toggle { /* not actually adjacent — handled below */ }
html:has(body.preview-mobile) {
  background: #06080b;
  /* Subtle "outside the phone" gradient so the desktop chrome reads
     as not-the-app. */
  background-image:
    radial-gradient(ellipse 70% 50% at 50% 0%, rgba(79,195,247,0.06), transparent 70%);
}
/* Floating Web/Mobile toggle button — mirrors the settings cog's neon
   language so the corner pair reads as a matched UI set. User report:
   "the mobile view button needs to be neon highlighted." Theme-aware
   ring + double box-shadow halo + glowing icon, with a stronger pulse
   on hover. */
.viewport-toggle {
  position: fixed;
  top: 14px; left: 14px;
  z-index: 600;
  width: 36px; height: 36px;
  background: #000000;
  border: 1px solid var(--theme-accent-bright, rgba(79,195,247,0.95));
  border-radius: 50%;
  color: var(--theme-accent-bright, #a8dcff);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  font-family: 'Rajdhani', sans-serif;
  text-shadow: 0 0 6px var(--theme-glow-outer, rgba(79,195,247,1));
  box-shadow:
    0 0 12px var(--theme-glow-outer, rgba(79,195,247,0.65)),
    0 0 24px var(--theme-glow-inner, rgba(79,195,247,0.30)),
    inset 0 0 0 1px var(--theme-wash-08, rgba(79,195,247,0.22));
  transition: transform 0.2s, box-shadow 0.25s, color 0.2s, background 0.2s, border-color 0.2s;
}
.viewport-toggle:hover {
  border-color: var(--theme-accent-bright, rgba(79,195,247,1));
  color: #ffffff;
  background: var(--theme-wash-08, rgba(79,195,247,0.08));
  transform: scale(1.08);
  box-shadow:
    0 0 16px var(--theme-glow-outer, rgba(79,195,247,0.95)),
    0 0 32px var(--theme-glow-inner, rgba(79,195,247,0.55)),
    inset 0 0 0 1px var(--theme-wash-15, rgba(79,195,247,0.30));
}
.viewport-toggle svg {
  width: 18px; height: 18px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 4px var(--theme-glow-outer, rgba(79,195,247,0.85)));
}
/* When in mobile-preview mode, slide the toggle outside the phone
   frame so it doesn't intrude on the simulated app surface. */
body.preview-mobile ~ .viewport-toggle,
body.preview-mobile .viewport-toggle {
  /* Toggle lives as direct body child; this just confirms styling. */
}
/* On real-phone-sized viewports, hide the toggle entirely — the user
   IS on a phone, no preview to toggle. */
@media (max-width: 520px) {
  .viewport-toggle { display: none; }
}
/* Hide the dev viewport-toggle on every screen EXCEPT the main menu
   and mode-select. User feedback: "the blue square on the top left
   corner needs to go" (re: the encyclopedia view). The toggle is a
   developer affordance, not part of the player UI — only surface it on
   landing screens. The body gets a `clb-toggle-hidden` class from
   ui.js whenever any non-landing phase/overlay is active. */
body.clb-toggle-hidden .viewport-toggle {
  display: none !important;
}
/* Ambient stage — a faint radial bloom at top-center + a barely-there
   circuit grid give the pure-black canvas a sense of depth without
   compromising the Tron aesthetic. Fixed so it doesn't scroll. */
body::before {
  content: "";
  position: fixed; inset: 0; pointer-events: none; z-index: 0;
  /* Top vignette = AI/enemy side, bottom vignette = player side.
     Was hardcoded blue/red; now follows --enemy-rgb / --player-rgb so
     a red-theme player sees a red bottom + blue top, etc. User
     feedback May-1: "the area to the left/right of the lanes feels
     kinda blue" — root cause was this vignette bleeding through the
     side gaps even when the active theme wasn't blue. */
  background:
    radial-gradient(ellipse 70% 55% at 50% 0%, rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.06), transparent 70%),
    radial-gradient(ellipse 70% 55% at 50% 100%, rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.04), transparent 70%);
}
body::after {
  content: "";
  position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background-image:
    linear-gradient(to right, rgba(var(--theme-rgb, 79,195,247), 0.035) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(var(--theme-rgb, 79,195,247), 0.035) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse 80% 70% at 50% 50%, #000 55%, transparent 100%);
  -webkit-mask-image: radial-gradient(ellipse 80% 70% at 50% 50%, #000 55%, transparent 100%);
  opacity: 0.55;
}
/* Pure black tarmac — matches the draft screen. Sleek, minimal. Colors pop. */
#game-area {
  position: relative;
  background: #000000;
}
#game-area > * { position: relative; z-index: 1; }

/* ---- PHASE TRANSITION BANNER ---- */
.phase-banner {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  display: flex; align-items: center; justify-content: center;
  z-index: 500; pointer-events: none;
  opacity: 0; transition: opacity 0.3s;
}
.phase-banner.active { opacity: 1; }
/* Phase banner — black pill with unified white glow. Matches HUD + lane pips. */
.phase-banner-text {
  font-family: 'Rajdhani', sans-serif;
  font-size: 36px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 5px; text-align: center;
  color: #f5fbff;
  position: relative; padding: 14px 36px;
  background: #000000;
  border: 1px solid rgba(255,255,255,0.90);
  border-radius: 6px;
  box-shadow:
    0 0 12px rgba(255,255,255,0.35),
    0 0 24px rgba(255,255,255,0.15);
  text-shadow: 0 0 8px rgba(255,255,255,0.35);
  animation: bannerSlideIn 1.6s cubic-bezier(0.22, 1, 0.36, 1);
}
/* Combat banner — was gold pill, but user feedback repeatedly:
   "little yellow blip when changing phases, get rid of it." The
   gold combat banner was the source of that flash on phase
   transitions. Now: theme-cyan (or white if no theme) to match
   the rest of the HUD chrome — no faction-conflicting gold flash
   when combat starts. */
.phase-banner-text.phase-combat {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79, 195, 247)) 65%, white);
  border-color: rgba(var(--theme-rgb, 79, 195, 247), 0.85);
  box-shadow:
    0 0 12px rgba(var(--theme-rgb, 79, 195, 247), 0.50),
    0 0 24px rgba(var(--theme-rgb, 79, 195, 247), 0.20);
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79, 195, 247), 0.50);
}
@keyframes bannerSlideIn {
  0%   { opacity: 0; transform: scale(0.85) translateY(12px); }
  15%  { opacity: 1; transform: scale(1.03) translateY(0); }
  25%  { transform: scale(1); }
  80%  { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.04) translateY(-6px); }
}

/* ---- TURN INFO HUD ---- */
.turn-hud {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  padding: 8px 16px;
  background: #000000;
  border-bottom: 1px solid rgba(255,255,255,0.25);
  font-size: 13px; font-weight: 600;
}
/* Neutral chrome — white glow, not blue. Matches the lane edges / centerlines. */
.hud-pill {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 5px 14px; border-radius: 999px;
  background: #000000;
  border: 1px solid rgba(255,255,255,0.90);
  box-shadow:
    0 0 12px rgba(255,255,255,0.35),
    0 0 24px rgba(255,255,255,0.15);
  transition: border-color 0.3s, box-shadow 0.3s;
}
/* HUD pill outline — tints by who went FIRST this round (round initiative).
   Blue = player opened, red = AI opened. The phase label INSIDE the pill
   carries the current-turn colour separately (see .hud-phase rules below).
   Applied via round-first-* body classes from UI.checkPhaseTransition. */
body.round-first-player .hud-pill-main {
  border-color: rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95);
  box-shadow:
    0 0 12px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.45),
    0 0 24px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.18);
}
body.round-first-ai .hud-pill-main {
  border-color: rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95);
  box-shadow:
    0 0 12px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.55),
    0 0 24px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.25);
}
.hud-pill-main { padding: 5px 13px; }

/* Legacy .hud-telemetry / .tel-* rules removed — the deck/tricks counts
   are now inline inside .hud-pill-main as .hud-count spans, so the
   separate telemetry container is no longer in the markup. */
/* Round label + number — Tron energy-orb styling for the current round.
   The word "Round" sits as a thin uppercase tag beside a bright circular
   number badge (black core + gold ring + double halo), picking up the same
   spec as the energy orb and round-pip.current. */
.hud-round {
  display: inline-flex; align-items: center; gap: 8px;
  color: #e6d9a8;
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700; font-size: 11px;
  /* Wider tracking on the label so "ROUND" reads as a Tron-HUD tag
     rather than an inline word. */
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 0 0 6px rgba(255,215,0,0.35);
  transition: color 0.3s, text-shadow 0.3s;
}
/* Label hue follows the round-opener too — same colour system as the
   badge itself so the whole "ROUND N" unit reads as one signal. */
body.round-first-player .hud-round {
  color: rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 1);
  text-shadow: 0 0 6px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.40);
}
body.round-first-ai     .hud-round {
  color: rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 1);
  text-shadow: 0 0 6px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.40);
}

.hud-round #round-num {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  width: 22px; height: 22px; padding: 0;
  background: transparent; border: none;
  /* Default to the active theme accent so the round-pip recolors with
     the user's selected neon (blue / red / green / purple). User
     report: "the round-1 diamond shows green even though my theme
     is blue." Round-first overrides below repaint per opener. */
  color: var(--theme-accent-bright, rgb(var(--theme-rgb, 79,195,247)));
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700; font-size: 13px;
  letter-spacing: 0;
  text-shadow:
    0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.95),
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.45);
  line-height: 1;
  font-variant-numeric: tabular-nums;
  transition: color 0.3s, text-shadow 0.3s;
}
.hud-round #round-num::before {
  content: '';
  position: absolute; inset: 1px;
  background: #000000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.95);
  transform: rotate(45deg);
  box-shadow:
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.22),
    0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.70),
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.32);
  z-index: -1;
  transition: border-color 0.3s, box-shadow 0.3s;
}
/* Round badge — repaint by round opener. Same Tron double-ring spec as the
   gold default, just the hue changes to signal initiative. */
body.round-first-player .hud-round #round-num {
  color: rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 1);
  text-shadow:
    0 0 6px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95),
    0 0 12px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.45);
}
body.round-first-player .hud-round #round-num::before {
  border-color: rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95);
  box-shadow:
    inset 0 0 0 1px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.22),
    0 0 10px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.70),
    0 0 22px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.32);
}
body.round-first-ai .hud-round #round-num {
  color: rgb(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60));
  text-shadow:
    0 0 6px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95),
    0 0 12px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.45);
}
body.round-first-ai .hud-round #round-num::before {
  border-color: rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95);
  box-shadow:
    inset 0 0 0 1px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.22),
    0 0 10px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.70),
    0 0 22px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.32);
}
.hud-phase {
  color: #f5fbff;
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700; font-size: 12px;
  /* Matched 1.4px tracking with .hud-round and .hud-count so the three
     text segments inside the pill read as one typographic family. */
  letter-spacing: 1.4px; text-transform: uppercase;
  text-shadow: 0 0 6px rgba(255,255,255,0.25);
  transition: color 0.3s, text-shadow 0.3s;
}
/* ============================================================
   FOCAL-HIERARCHY POLISH (Tier 3 polish-pass)
   ============================================================
   "At any moment, ONE element is THE thing." Whoever's acting
   gets max glow; the inactive side dims so the eye lands on the
   right place automatically. Builds on the existing edge-glow
   strip (below) — that's the AMBIENT cue; this is the focal
   layer that promotes the active info-bar.

   Default behavior: both bars share their normal glow. With
   `body.turn-player` or `body.turn-ai`, the active side ramps
   UP and the inactive side ramps DOWN. Leaving combat returns
   both to baseline. Animations tied to the existing 2s edge
   pulse so the transition reads as one cohesive system.
   ============================================================ */
body.turn-player .info-bar.player-bar,
body.turn-ai     .info-bar.ai-bar {
  /* Active side — focal glow, full opacity. Same color base as
     the bar's own theme color; just brightened. */
  filter: brightness(1.04) saturate(1.10);
}
body.turn-player .info-bar.ai-bar,
body.turn-ai     .info-bar.player-bar {
  /* Inactive side — dim 30%. Doesn't disappear (player still
     needs to see HP) but visually recedes so the active bar
     pops by contrast. */
  filter: brightness(0.62) saturate(0.85);
  opacity: 0.85;
}
body.turn-player .info-bar.player-bar,
body.turn-ai     .info-bar.ai-bar,
body.turn-player .info-bar.ai-bar,
body.turn-ai     .info-bar.player-bar {
  transition: filter 0.35s cubic-bezier(0.2, 0, 0, 1), opacity 0.35s cubic-bezier(0.2, 0, 0, 1);
}

/* Phase label — tints by CURRENT turn (not round opener). So the pill outline
   holds the round-opener colour while the phase word tracks who's acting now. */
body.turn-player .hud-phase {
  color: rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 1);
  text-shadow:
    0 0 6px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.65),
    0 0 12px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.30);
}
body.turn-ai .hud-phase {
  color: rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 1);
  text-shadow:
    0 0 6px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.70),
    0 0 12px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.35);
}
body.turn-combat .hud-phase {
  color: #ffd77a;
  text-shadow: 0 0 6px rgba(255,215,0,0.70), 0 0 12px rgba(255,215,0,0.35);
}

/* ============================================================
   WHOSE-TURN EDGE GLOW
   ----------------------------------------------------------------
   Fixed 6px edge bar — bottom for the player, top for the AI, both
   pulsing gold during combat. Gives an at-a-glance cue that
   answers "whose turn is it" without needing to read the HUD.
   pointer-events:none so it never steals clicks. ============================================================ */
body::before,
body::after {
  content: '';
  position: fixed; left: 0; right: 0;
  height: 6px;
  pointer-events: none;
  z-index: 90;
  opacity: 0;
  transition: opacity 0.25s ease;
}
/* Top edge = AI/enemy turn glow → --enemy-rgb (red default; flips
   when player picks red theme). Bottom edge = player turn glow →
   --player-rgb (blue default; follows active theme). */
body::before { top: 0;    background: linear-gradient(to bottom, rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.75), transparent); box-shadow: 0 0 22px 2px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.55); }
body::after  { bottom: 0; background: linear-gradient(to top,   rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.75), transparent); box-shadow: 0 0 22px 2px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.55); }
body.turn-player::after { opacity: 1; animation: turnEdgePulse 2s ease-in-out infinite; }
body.turn-ai::before    { opacity: 1; animation: turnEdgePulse 2s ease-in-out infinite; }
body.turn-combat::before,
body.turn-combat::after {
  opacity: 1;
  background: linear-gradient(to top, rgba(255,215,0,0.75), transparent);
  box-shadow: 0 0 22px 2px rgba(255,215,0,0.55);
  animation: turnEdgePulse 1.1s ease-in-out infinite;
}
body.turn-combat::before { background: linear-gradient(to bottom, rgba(255,215,0,0.75), transparent); }
@keyframes turnEdgePulse {
  0%, 100% { opacity: 0.55; }
  50%      { opacity: 1; }
}
/* Dividers — rotated squares (Tron "circuit node" / tap-point) instead of
   round dots. Reads as a signal pickup on a trace line connecting the
   segments of the HUD pill. */
.hud-divider {
  width: 5px; height: 5px; border-radius: 0;
  transform: rotate(45deg);
  background: rgba(255,255,255,0.92);
  box-shadow: 0 0 5px rgba(255,255,255,0.65), 0 0 10px rgba(255,255,255,0.35);
}
.hud-divider.hud-divider-cyan {
  background: rgb(var(--theme-rgb, 79,195,247));
  box-shadow:
    0 0 5px rgba(var(--theme-rgb, 79,195,247), 1),
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.55);
}
.hud-divider.hud-divider-purple {
  /* Amethyst node — same purple family as the trick cards. */
  background: #d7b3e6;
  box-shadow: 0 0 5px rgba(155,89,182,1), 0 0 12px rgba(155,89,182,0.70);
}
/* Inline deck/tricks counts — label is a wide-tracked uppercase tag, number
   sits in a rectangular mini-frame with a neon hairline edge (cyan for deck,
   purple for tricks). The frame reads as a Tron telemetry readout rather
   than just inline text. */
.hud-count {
  font-family: 'Rajdhani', sans-serif;
  font-size: 10.5px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  text-indent: 2px;
  display: inline-flex; align-items: center; gap: 7px;
}
.hud-count b {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 26px; height: 20px; padding: 0 6px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 13px; font-weight: 700;
  letter-spacing: 0;
  font-variant-numeric: tabular-nums;
  border-radius: 3px;
  background: #000000;
  /* Default (overridden by hud-count-deck/tricks below). */
  border: 1px solid rgba(255,255,255,0.55);
  transition: border-color 0.3s, box-shadow 0.3s, color 0.3s;
}
.hud-count-deck { color: rgb(var(--theme-rgb, 79,195,247)); }
.hud-count-deck b {
  color: rgb(var(--theme-rgb, 79,195,247));
  border-color: rgba(var(--theme-rgb, 79,195,247), 0.95);
  box-shadow:
    0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.55),
    0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.25),
    inset 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.10);
  text-shadow:
    0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.90),
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.45);
}
.hud-count-tricks { color: #d7b3e6; }
.hud-count-tricks b {
  color: #d7b3e6;
  border-color: rgba(155,89,182,0.95);
  box-shadow: 0 0 8px rgba(155,89,182,0.60), 0 0 14px rgba(155,89,182,0.30), inset 0 0 6px rgba(155,89,182,0.12);
  text-shadow: 0 0 6px rgba(155,89,182,0.95), 0 0 12px rgba(155,89,182,0.50);
}

/* ---- INFO BARS (Enemy above lanes, Player below lanes) ---- */
/* Identical grid for both banners — guarantees column alignment + equal height */
.info-bar {
  display: grid;
  grid-template-columns: 220px 64px 1fr 64px 96px;
  align-items: center;
  padding: 10px 20px;
  gap: 16px;
  height: 64px;
  box-sizing: border-box;
  /* Sit ABOVE the Tron cursor-trail SVG (#tron-cursor-trail
     z-index 200) so the trail's mix-blend-mode: screen can't paint
     cyan over the HP bar, block circle, energy diamond, etc. User
     report 2026-05-18: "when I have more blue than red, there's
     like a little blue section on their health bar." The cursor
     trail was screen-blending its theme color onto the dark bar
     background, which read as the player's blue encroaching into
     the enemy's red HP bar. Raising the HUD strip above the trail
     keeps the trail visible everywhere else (board surface, hand,
     menus) without contaminating the score-read chrome. */
  position: relative;
  z-index: 210;
}
.bar-cell { display: flex; align-items: center; height: 100%; }
/* Explicit grid-column pins each cell to its intended track. Required because
   the .actions-section cell is position:absolute for banner-midpoint centering
   (see block below); without explicit columns, grid auto-flow would place the
   subsequent cells (bar-energy, bar-dead) into the vacated tracks, collapsing
   the layout and causing the energy orb to render over the Done button. */
.bar-hp     { grid-column: 1; justify-content: flex-start; }
.bar-block  { grid-column: 2; justify-content: center; }
.bar-center { grid-column: 3; justify-content: center; min-width: 0; }
.bar-energy { grid-column: 4; justify-content: center; }
.bar-dead   { grid-column: 5; justify-content: flex-end; }

/* Banners glow at the same perceived brightness as the white chrome. Red and
   blue need higher alpha than white to appear equally luminous. */
.info-bar.ai-bar {
  background:
    linear-gradient(180deg, rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.08), transparent 50%),
    linear-gradient(180deg, #0a0f18, #07080f);
  border-top: 1px solid rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95);
  border-bottom: 1px solid rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.95);
  box-shadow:
    0 0 12px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.65),
    0 0 24px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.30),
    inset 0 1px 0 rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.30),
    inset 0 -1px 0 rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.30);
}
.info-bar.player-bar {
  background:
    linear-gradient(0deg, rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.08), transparent 50%),
    linear-gradient(180deg, #07080f, #0a0f18);
  border-top: 1px solid rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95);
  border-bottom: 1px solid rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.95);
  box-shadow:
    0 0 12px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.55),
    0 0 24px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.25),
    inset 0 1px 0 rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.30),
    inset 0 -1px 0 rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.30);
}

/* Mini enemy hand centered in the enemy banner */
.ai-hand-mini .hand-cards {
  display: flex; gap: 4px; padding: 0; min-height: 0;
  flex-wrap: nowrap; align-items: center; justify-content: center;
}
/* Opponent hand pips — black core + red/green ring + diamond-pattern SVG inside */
.ai-hand-mini .card-back {
  width: 20px; height: 30px;
  background: #000000;
  border-radius: 3px;
  border: 1px solid rgba(231,76,60,0.95);
  color: rgba(231,76,60,0.85);
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 0 8px rgba(231,76,60,0.45), 0 0 16px rgba(231,76,60,0.18);
  flex-shrink: 0;
  overflow: hidden;
}
.ai-hand-mini .card-back svg { width: 100%; height: 100%; display: block; }
.ai-hand-mini .card-back.trick-back {
  border-color: rgba(155,89,182,0.95);
  color: rgba(155,89,182,0.85);
  box-shadow: 0 0 8px rgba(155,89,182,0.45), 0 0 16px rgba(155,89,182,0.18);
}

/* Block Meter — Tron ring matching the energy orb: black core, bright colored
   edge, glowing double-halo. No conic progress dial and no dull grey track —
   progress is expressed via the "X/8" number inside. Per-side color overrides
   below paint it blue (player) / red (AI). Default here is gold as a safety
   fallback; every instance is scoped under .player-bar or .ai-bar in practice. */
.block-circle {
  --fill: 0%;
  width: 44px; height: 44px; border-radius: 50%;
  position: relative;
  background: #000000;
  border: 1px solid rgba(255,215,0,0.95);
  box-shadow: 0 0 12px rgba(255,215,0,0.60), 0 0 24px rgba(255,215,0,0.25);
  transition: border-color 0.25s, box-shadow 0.25s, background 0.25s;
  display: flex; align-items: center; justify-content: center;
}
.block-circle-label { display: none; }
.block-circle-value {
  position: relative; z-index: 1;
  font-family: 'Rajdhani', sans-serif;
  font-size: 12px; font-weight: 700; letter-spacing: 0.3px;
  color: #f5fbff;
  text-shadow: 0 0 6px rgba(255,255,255,0.35);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
/* Full state — gold ring fully lit. Idle pulse DISABLED per
   user feedback: "Get rid of these running animations of the
   block meter." A solid bright gold glow at 8/8 still reads as
   "ready" without continuous motion. */
.block-circle.full {
  background: conic-gradient(from -90deg, rgba(255,215,0,0.95) 0 100%, rgba(255,215,0,0.95) 100%);
  box-shadow: 0 0 14px rgba(255,215,0,0.80), 0 0 28px rgba(255,215,0,0.40);
  animation: none;
}
.block-circle.full .block-circle-value { color: #ffd77a; text-shadow: 0 0 8px rgba(255,215,0,0.85); }
@keyframes blockFullPulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.75; }
}

/* Per-side block-circle theming — Tron ring, per-side color. Player blue, AI
   red. Matches each side's banner hue so the block meter reads as part of the
   same energy spec as the HP bar and energy orb. */
.player-bar .block-circle {
  background: #000000;
  border-color: rgba(var(--theme-rgb, 79,195,247), 0.95);
  box-shadow: 0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.60), 0 0 24px rgba(var(--theme-rgb, 79,195,247), 0.25);
}
.player-bar .block-circle.full {
  background: #000000;
  border-color: rgba(var(--theme-rgb, 79,195,247), 0.95);
  box-shadow: 0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.95), 0 0 28px rgba(var(--theme-rgb, 79,195,247), 0.45);
}
.player-bar .block-circle-value {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.70);
}
.player-bar .block-circle.full .block-circle-value {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  text-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.95);
}
.ai-bar .block-circle {
  background: #000000;
  border-color: rgba(231,76,60,0.95);
  box-shadow: 0 0 12px rgba(231,76,60,0.60), 0 0 24px rgba(231,76,60,0.25);
}
.ai-bar .block-circle.full {
  background: #000000;
  border-color: rgba(231,76,60,0.95);
  box-shadow: 0 0 14px rgba(231,76,60,0.95), 0 0 28px rgba(231,76,60,0.45);
}
.ai-bar .block-circle-value {
  color: #ff8a7a;
  text-shadow: 0 0 8px rgba(231,76,60,0.70);
}
.ai-bar .block-circle.full .block-circle-value {
  color: #ffd0ca;
  text-shadow: 0 0 10px rgba(231,76,60,0.95);
}

/* Action buttons integrated into the player banner. The .bar-center grid
   cell (col 3) sits between the block circle and the energy orb, so letting
   the cell's own justify-content: center handle alignment gives the Undo +
   Done pair a visual midpoint that matches the gap between its flanking
   elements — which reads as "centered" to the eye even though the banner
   grid has asymmetric outer columns. */
.actions-section {
  gap: 6px; min-width: 0; overflow: hidden;
  flex-wrap: nowrap;
}
.actions-section .btn {
  /* Asymmetric vertical padding compensates for Rajdhani's cap metrics: at
     12px the actual glyph ascent is ~7.7px vs a 15px em-box, so uppercase
     caps sit in the top half of the em — visually the text looks low when
     the line-box is perfectly centered. Adding padding-bottom shrinks the
     flex content box so align-items:center places glyphs ~2px higher. */
  padding: 0 14px 4px; font-size: 11.5px; letter-spacing: 1px;
  /* Match text-indent to this rule's own letter-spacing (base .btn uses 1.8px). */
  text-indent: 1px;
  height: 30px; line-height: 1;
  display: inline-flex; align-items: center; justify-content: center;
  white-space: nowrap;
  min-width: 0;
  text-overflow: ellipsis; overflow: hidden;
  flex-shrink: 1;
}
/* Undo is short; keep it at its natural size */
.actions-section #btn-undo { flex-shrink: 0; }

/* Health Bars — Hearthstone style */
.health-container { display: flex; align-items: center; gap: 8px; position: relative; }

/* Frozen HP shield (Mr. Freeze) */
.health-container.hp-frozen {
  padding: 4px 10px;
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(133,193,233,0.12), rgba(174,214,241,0.05)),
    repeating-linear-gradient(45deg, rgba(174,214,241,0.08) 0 4px, transparent 4px 8px);
  box-shadow:
    0 0 14px rgba(133,193,233,0.55),
    0 0 26px rgba(174,214,241,0.3),
    inset 0 0 10px rgba(174,214,241,0.25),
    inset 0 1px 0 rgba(255,255,255,0.3);
  border: 1px solid rgba(174,214,241,0.5);
}
.health-container.hp-frozen::before {
  content: '❄';
  position: absolute; left: -20px; top: 50%;
  transform: translateY(-50%);
  font-size: 18px; color: #aed6f1;
  text-shadow: 0 0 8px rgba(133,193,233,0.9), 0 0 14px rgba(174,214,241,0.5);
  pointer-events: none;
  /* Sit ABOVE any red HP-bar box-shadow that leaks leftward from the
     adjacent .health-bar — keeps the snowflake reading on a clean
     dark backdrop instead of a red wash. */
  z-index: 2;
}
/* When the HP bar is frozen, the underlying .health-bar should glow
   in the freeze hue instead of the side color (red for AI, cyan for
   player). Same rule applies to both sides — without it, the AI's red
   box-shadow leaks behind the snowflake icon and reads as a red halo
   around the freeze marker. User report: "fix the red behind the
   snowflake, it may happen for my side as well." */
.health-container.hp-frozen .health-bar {
  border-color: rgba(174,214,241,0.95) !important;
  box-shadow:
    0 0 10px rgba(133,193,233,0.55),
    0 0 22px rgba(174,214,241,0.22) !important;
}
.health-container.hp-frozen::after {
  content: 'FROZEN';
  position: absolute; left: 50%; top: -12px;
  transform: translateX(-50%);
  font-size: 9px; font-weight: 900; letter-spacing: 2px;
  color: #aed6f1;
  text-shadow: 0 0 6px rgba(133,193,233,0.8), 0 0 12px rgba(174,214,241,0.6);
  pointer-events: none;
  white-space: nowrap;
}

/* HP bars — black light channel with a colored fill that glows */
.health-bar {
  width: 160px; height: 16px; background: #000000;
  border-radius: 3px; overflow: hidden;
  border: 1px solid rgba(255,255,255,0.30);
  position: relative;
}
.player-bar .health-bar {
  border-color: rgba(var(--theme-rgb, 79,195,247), 0.95);
  box-shadow: 0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.55), 0 0 24px rgba(var(--theme-rgb, 79,195,247), 0.22);
}
.ai-bar .health-bar {
  border-color: rgba(231,76,60,0.95);
  box-shadow: 0 0 12px rgba(231,76,60,0.55), 0 0 24px rgba(231,76,60,0.25);
}
/* Hollow fill + bright leading edge — the track stays dark, the fill is a
   low-opacity color wash, and a 2px neon line glows at the HP boundary. */
.health-fill {
  height: 100%;
  /* Width transition uses ease-out-quart (sharp drop, smooth tail)
     so HP loss reads as decisive — the bar punches down quickly
     then settles. ease (default cubic) was floaty. Slightly longer
     duration (0.5 → 0.6s) compensates for the steeper curve. */
  transition: width 0.6s cubic-bezier(0.25, 1, 0.5, 1);
  position: relative;
}
/* Brief bright pulse on the leading edge when HP drains. Triggered
   by adding .hp-edge-pulse for 320ms on damage events from JS. */
.health-fill.hp-edge-pulse {
  animation: hpEdgePulse 320ms cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes hpEdgePulse {
  0%   { filter: brightness(1.0); }
  35%  { filter: brightness(1.55) saturate(1.2); }
  100% { filter: brightness(1.0); }
}
@media (prefers-reduced-motion: reduce) {
  .health-fill { transition: width 80ms linear; }
  .health-fill.hp-edge-pulse { animation: none; }
}

/* ============================================================
   HIT-PAUSE — full-board freeze-frame on lethal hits.
   ============================================================
   Adds .hit-pause to <body> for 90ms on death events. ALL CSS
   animations and transitions on the board pause for that beat.
   Then everything resumes. This is the cel-animation/AAA trick
   that makes a kill register as an event instead of a blip —
   without it the eye sees too much continuous motion to lock
   onto the moment of death. Tuned at 90ms: 1 frame at 30fps,
   ~5 frames at 60fps. Long enough to read, short enough that
   gameplay flow isn't interrupted. */
body.hit-pause .board *,
body.hit-pause .board-section *,
body.hit-pause .player-hand *,
body.hit-pause .ai-hand * {
  animation-play-state: paused !important;
  /* Freeze in-flight transitions too via a 0s transition override.
     The current property values stick during the pause; when the
     class is removed, transitions resume from there. */
  transition-duration: 0ms !important;
}
@media (prefers-reduced-motion: reduce) {
  body.hit-pause .board *,
  body.hit-pause .board-section *,
  body.hit-pause .player-hand *,
  body.hit-pause .ai-hand * { animation-play-state: running !important; }
}

/* Stat number tick-up — wraps the current ATK/HP digit while it
   counts from old → new value. Clean monospaced look so the digit
   width doesn't jitter as the number changes. */
.stat-tickup {
  font-variant-numeric: tabular-nums;
  display: inline-block;
}
/* HP fill — colored wash with a bright 2px leading edge that cuts into the
   black channel. Stronger glow makes it read as an illuminated pipe. */
.health-fill.player-hp {
  background: linear-gradient(90deg, rgba(var(--theme-rgb, 79,195,247), 0.08), rgba(var(--theme-rgb, 79,195,247), 0.20));
  box-shadow:
    inset -2px 0 0 0 rgba(168,220,255,1),
    2px 0 6px rgba(var(--theme-rgb, 79,195,247), 0.90),
    4px 0 12px rgba(var(--theme-rgb, 79,195,247), 0.55),
    6px 0 20px rgba(var(--theme-rgb, 79,195,247), 0.25);
}
.health-fill.ai-hp {
  background: linear-gradient(90deg, rgba(231,76,60,0.08), rgba(231,76,60,0.24));
  box-shadow:
    inset -2px 0 0 0 rgba(255,138,122,1),
    2px 0 6px rgba(231,76,60,0.90),
    4px 0 12px rgba(231,76,60,0.55),
    6px 0 20px rgba(231,76,60,0.25);
}
/* Hide the leading edge when the bar is full (100%) — there's no boundary to mark. */
.health-fill.player-hp[style*="width: 100%"],
.health-fill.player-hp[style*="width:100%"] {
  box-shadow:
    inset 0 0 0 1px rgba(168,220,255,0.22),
    0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.30);
}
.health-fill.ai-hp[style*="width: 100%"],
.health-fill.ai-hp[style*="width:100%"] {
  box-shadow:
    inset 0 0 0 1px rgba(255,150,140,0.20),
    0 0 6px rgba(231,76,60,0.25);
}
.health-text {
  font-weight: 700; font-size: 20px; min-width: 38px; text-align: center;
  letter-spacing: 0.5px;
  font-variant-numeric: tabular-nums;
  font-family: 'SF Mono', 'Menlo', 'Consolas', monospace;
  line-height: 1;
}
.health-text.player-color {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  text-shadow:
    0 0 4px rgba(var(--theme-rgb, 79,195,247), 0.95),
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.55),
    0 1px 2px rgba(0,0,0,0.8);
}
.health-text.ai-color {
  color: #ffc4b9;
  text-shadow:
    0 0 4px rgba(231,76,60,0.95),
    0 0 12px rgba(231,76,60,0.55),
    0 1px 2px rgba(0,0,0,0.8);
}

/* Block Meter — clean bar */
.block-container { display: flex; align-items: center; gap: 6px; }
.block-bar {
  width: 100px; height: 14px; background: #1a1a2a;
  border-radius: 7px; overflow: hidden; border: 1px solid #2980b9;
  box-shadow: inset 0 1px 4px rgba(0,0,0,0.4);
}
.block-fill {
  height: 100%; transition: width 0.4s ease; border-radius: 6px;
  background: linear-gradient(90deg, #2980b9, #3498db);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.2);
}
.block-text { font-size: 12px; color: #3498db; font-weight: 700; min-width: 30px; }

/* Energy — matches card cost badge (top-left gold circle) */
.energy-display { display: flex; align-items: center; gap: 4px; }
.energy-orb {
  width: 14px; height: 14px; border-radius: 50%;
  border: 2px solid #e67e22;
  transition: background 0.25s, box-shadow 0.25s;
}
.energy-orb.filled {
  background: radial-gradient(circle at 35% 35%, #ffd700, #f39c12);
  box-shadow: 0 2px 6px rgba(0,0,0,0.4), 0 0 4px rgba(243,156,18,0.3);
  border-color: #e67e22;
}
.energy-orb.empty {
  background: radial-gradient(circle at 35% 35%, #3a2b18, #1f160c);
  box-shadow: inset 0 1px 3px rgba(0,0,0,0.5);
  border-color: #5a3e20;
}
/* Main energy — Tron ring: dark core with glowing gold edge, number inside.
   Gold here is the LEGENDARY rarity gold (#ffe066 / rgba(255,215,0)) with a
   matching double-halo, so the player/AI energy orb reads as the same
   "legendary yellow" treatment used for the 9/10-cost rarity tier. */
.energy-text {
  position: relative;
  width: 44px; height: 44px;
  background: transparent;
  border: none;
  color: #ffe066;
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700; font-size: 17px;
  display: inline-flex; align-items: center; justify-content: center;
  text-shadow: 0 0 6px rgba(255,215,0,0.95), 0 0 14px rgba(255,215,0,0.55);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
/* Diamond backdrop — matches the card cost diamond. Player-side orb
   picks up the active theme color; AI-side orb stays red; the HUD
   (center/overall) keeps gold as the currency-universal default.
   Scoped by parent context so one rule set covers all three contexts. */
.energy-text::before {
  content: '';
  position: absolute; inset: 4px;
  background: #000000;
  border: 1px solid rgba(255,215,0,1);
  transform: rotate(45deg);
  box-shadow:
    0 0 12px rgba(255,215,0,0.80),
    0 0 24px rgba(255,215,0,0.40);
  z-index: -1;
}
.player-bar .energy-text {
  color: rgb(var(--theme-rgb, 79,195,247));
  text-shadow:
    0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.95),
    0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.55);
}
.player-bar .energy-text::before {
  border-color: rgba(var(--theme-rgb, 79,195,247), 1);
  box-shadow:
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.80),
    0 0 24px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
.ai-bar .energy-text {
  color: rgb(231,76,60);
  text-shadow: 0 0 6px rgba(231,76,60,0.95), 0 0 14px rgba(231,76,60,0.55);
}
.ai-bar .energy-text::before {
  border-color: rgba(231,76,60,1);
  box-shadow: 0 0 12px rgba(231,76,60,0.80), 0 0 24px rgba(231,76,60,0.40);
}

/* Pile Badges — icon + number */
.pile-badge {
  padding: 5px 10px; border-radius: 999px; font-size: 12px; font-weight: 800;
  letter-spacing: 0.3px;
  display: inline-flex; align-items: center; gap: 5px; cursor: default;
}
/* Default: hide opponent deck/trick mini-badges on desktop (the central
   HUD pill already shows shared counts). The mobile container-query
   block re-shows them. */
.pile-badge-mobile-only { display: none; }
.pile-icon {
  width: 12px; height: 12px; display: inline-block;
  background-size: contain; background-repeat: no-repeat; background-position: center;
  opacity: 0.9;
}
/* Skull icon (Dead) — red by default (AI side); player side overrides below with blue. */
.icon-dead {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path d='M8 1.5c-3 0-5.5 2.3-5.5 5.2 0 1.6 0.8 3 2 3.9v2.1c0 0.6 0.5 1 1 1h5c0.5 0 1-0.4 1-1v-2.1c1.2-0.9 2-2.3 2-3.9 0-2.9-2.5-5.2-5.5-5.2z' fill='%23e74c3c'/><circle cx='6' cy='7' r='1.1' fill='%23081624'/><circle cx='10' cy='7' r='1.1' fill='%23081624'/></svg>");
}
.player-bar .icon-dead {
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'><path d='M8 1.5c-3 0-5.5 2.3-5.5 5.2 0 1.6 0.8 3 2 3.9v2.1c0 0.6 0.5 1 1 1h5c0.5 0 1-0.4 1-1v-2.1c1.2-0.9 2-2.3 2-3.9 0-2.9-2.5-5.2-5.5-5.2z' fill='%234fc3f7'/><circle cx='6' cy='7' r='1.1' fill='%23081624'/><circle cx='10' cy='7' r='1.1' fill='%23081624'/></svg>");
}
/* Pile badges inside the HUD — numbers go white so they don't compete with
   the white chrome. The icons keep their semantic color (blue deck / green
   sparkle) as small legends. No border — the HUD pill already frames them. */
.pile-badge.draw-pile {
  background: transparent; color: #f5fbff;
  border: none; box-shadow: none;
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700;
  text-shadow: 0 0 6px rgba(255,255,255,0.25);
}
.pile-badge.trick-pile {
  background: transparent; color: #f5fbff;
  border: none; box-shadow: none;
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700;
  text-shadow: 0 0 6px rgba(255,255,255,0.25);
}
.pile-badge.dead-pile {
  background: #000000; color: #ff8a7a;
  border: 1px solid rgba(231,76,60,0.95); cursor: pointer;
  padding: 6px 12px; font-size: 13px;
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700;
  box-shadow: 0 0 12px rgba(231,76,60,0.55), 0 0 24px rgba(231,76,60,0.25);
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s, color 0.2s, transform 0.15s;
}
.pile-badge.dead-pile:hover {
  background: rgba(231,76,60,0.14); color: #ffd0ca;
  border-color: rgba(231,76,60,0.85);
  box-shadow: 0 0 14px rgba(231,76,60,0.55), inset 0 0 10px rgba(231,76,60,0.12);
  transform: translateY(-1px);
}
/* Player-side dead pile — blue chrome matching the player banner. The skull
   icon uses its own SVG fill so we leave it alone (still red skull = universal
   "dead" semantics) and only repaint the badge frame. */
.player-bar .pile-badge.dead-pile {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  border-color: rgba(var(--theme-rgb, 79,195,247), 0.95);
  box-shadow: 0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.55), 0 0 24px rgba(var(--theme-rgb, 79,195,247), 0.22);
}
.player-bar .pile-badge.dead-pile:hover {
  background: rgba(var(--theme-rgb, 79,195,247), 0.14); color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  border-color: rgba(var(--theme-rgb, 79,195,247), 0.85);
  box-shadow: 0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.55), inset 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.12);
}

/* Trick-history badge — same chrome as dead-pile but tinted purple
   (the trick palette). One per side, sits next to the dead pile. */
.pile-badge.tricks-history {
  background: #000000;
  color: #d7b3e6;
  border: 1px solid rgba(155,89,182,0.85);
  cursor: pointer;
  padding: 6px 12px;
  font-size: 13px;
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700;
  box-shadow: 0 0 12px rgba(155,89,182,0.45), 0 0 24px rgba(155,89,182,0.18);
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s, color 0.2s, transform 0.15s;
  margin-right: 6px;
}
.pile-badge.tricks-history:hover {
  background: rgba(155,89,182,0.14);
  color: #ecd6f5;
  border-color: rgba(155,89,182,1);
  box-shadow: 0 0 14px rgba(155,89,182,0.65), inset 0 0 10px rgba(155,89,182,0.14);
  transform: translateY(-1px);
}
.pile-badge.tricks-history .pile-icon.icon-tricks {
  color: #d7b3e6;
  text-shadow: 0 0 6px rgba(215,179,230,0.6);
  font-size: 14px;
  line-height: 1;
}
/* History-trick card inside the overlay — same .trick-card chrome
   the in-hand renderer uses. Just centered + non-interactive. */
.dead-pile-overlay .history-trick {
  width: 160px;
  pointer-events: none;
  margin: 6px;
}

.pile-info { display: flex; gap: 6px; align-items: center; }


/* ---- MODE SELECT OVERLAY — pre-match mode picker ----
   Same black backdrop as the draft overlay so the two screens feel like
   steps in the same Tron chrome. Two rows (1v1, 2v2) × two columns
   (Classic, Deckbuilder). Only 1v1 Classic is enabled in phase 1. */
.mode-select-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  display: flex; align-items: center; justify-content: center;
  z-index: 210;
  background: #000000;
}
.mode-panel {
  max-width: 820px; width: 92%;
  padding: 48px 40px 44px;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  border-radius: 4px;
  box-shadow:
    0 0 24px rgba(var(--theme-rgb, 79,195,247), 0.30),
    0 0 56px rgba(var(--theme-rgb, 79,195,247), 0.14),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.08);
  position: relative;
}
.mode-title {
  font-family: 'Rajdhani', sans-serif;
  font-size: 36px; font-weight: 700;
  letter-spacing: 8px; text-transform: uppercase;
  text-align: center; margin: 0 0 6px;
  color: #f5fbff;
  text-shadow:
    0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.80),
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
.mode-subtitle {
  font-family: 'Rajdhani', sans-serif;
  font-size: 12px; font-weight: 600;
  letter-spacing: 4px; text-transform: uppercase;
  text-align: center; color: #8fc8ee;
  margin-bottom: 30px;
  text-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.35);
}
.mode-grid {
  display: grid;
  grid-template-columns: 140px 1fr 1fr;
  grid-auto-rows: auto;
  gap: 14px 14px;
  align-items: stretch;
}
.mode-row-label {
  font-family: 'Rajdhani', sans-serif;
  font-size: 13px; font-weight: 700;
  letter-spacing: 3px; text-transform: uppercase;
  color: #e8f5ff;
  display: flex; align-items: center; justify-content: flex-end;
  padding-right: 6px;
  text-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.35);
}
.mode-option {
  /* Base button: Tron capsule, black core, cyan ring. Hover raises the ring
     brightness. Disabled variant dims to grey + grey border. */
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.70);
  border-radius: 4px;
  padding: 18px 16px 16px;
  text-align: left;
  cursor: pointer;
  color: #f5fbff;
  font-family: 'Rajdhani', sans-serif;
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s, opacity 0.2s;
  box-shadow:
    0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.22),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.06);
  position: relative;
}
.mode-option:hover {
  transform: translateY(-2px);
  border-color: rgba(var(--theme-rgb, 79,195,247), 1);
  box-shadow:
    0 0 18px rgba(var(--theme-rgb, 79,195,247), 0.60),
    0 0 36px rgba(var(--theme-rgb, 79,195,247), 0.25),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.18);
}
.mode-option-label {
  font-size: 18px; font-weight: 700;
  letter-spacing: 3px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.70);
  margin-bottom: 6px;
}
.mode-option-sub {
  font-size: 12px; font-weight: 500;
  letter-spacing: 0.5px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white);
  line-height: 1.4;
}
.mode-option-disabled {
  cursor: not-allowed;
  opacity: 0.38;
  border-color: rgba(150,160,170,0.45);
  box-shadow: 0 0 6px rgba(150,160,170,0.12);
}
.mode-option-disabled:hover {
  transform: none;
  border-color: rgba(150,160,170,0.45);
  box-shadow: 0 0 6px rgba(150,160,170,0.12);
}
.mode-option-disabled .mode-option-label {
  color: #8690a0;
  text-shadow: none;
}
.mode-option-note {
  margin-top: 8px;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  color: #d7b3e6;
  text-shadow: 0 0 5px rgba(155,89,182,0.55);
}

/* ============================================================
   MAIN MENU OVERLAY (phase 4a) — top-level landing screen.
   Five large buttons arranged vertically; each is a capsule with an
   icon + label + subtitle. Matches the same Tron chrome as the mode
   picker so PLAY → mode picker feels continuous.
   ============================================================ */
.main-menu-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  display: flex; align-items: center; justify-content: center;
  z-index: 215;
  background: #000000;
}
.mm-panel {
  position: relative;
  max-width: 580px; width: 92%;
  padding: 52px 48px 38px;
  background:
    linear-gradient(180deg, rgba(var(--theme-rgb, 79,195,247), 0.05) 0%, rgba(0,0,0,0) 40%),
    #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  border-radius: 4px;
  box-shadow:
    0 0 32px rgba(var(--theme-rgb, 79,195,247), 0.30),
    0 0 72px rgba(var(--theme-rgb, 79,195,247), 0.14),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.08),
    inset 0 1px 0 rgba(var(--theme-rgb, 79,195,247), 0.35);
}
/* Corner brackets — L-shaped HUD marks at each corner of the panel.
   Pure border trick: a 14px square with two borders showing, creates the
   bracket. Four span-less corners via pseudo-elements is not enough (only
   two), so the remaining two are drawn with box-shadow offsets. */
.mm-panel::before,
.mm-panel::after {
  content: "";
  position: absolute;
  width: 16px; height: 16px;
  pointer-events: none;
}
.mm-panel::before {
  top: -1px; left: -1px;
  border-top: 2px solid rgb(var(--theme-rgb, 79,195,247));
  border-left: 2px solid rgb(var(--theme-rgb, 79,195,247));
  filter: drop-shadow(0 0 6px rgba(var(--theme-rgb, 79,195,247),0.75));
}
.mm-panel::after {
  bottom: -1px; right: -1px;
  border-bottom: 2px solid rgb(var(--theme-rgb, 79,195,247));
  border-right: 2px solid rgb(var(--theme-rgb, 79,195,247));
  filter: drop-shadow(0 0 6px rgba(var(--theme-rgb, 79,195,247),0.75));
}
/* Tiny uppercase brand tag above the title — positions the product name
   so the hero word ("the game") lands as the focal display type. */
.mm-tag {
  font-family: 'Rajdhani', sans-serif;
  font-size: 10px; font-weight: 700;
  letter-spacing: 5px; text-transform: uppercase;
  text-align: center;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 75%, white);
  opacity: 0.82;
  margin-bottom: 10px;
  text-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.45);
}
.mm-title {
  font-family: 'Rajdhani', sans-serif;
  font-size: 52px; font-weight: 700;
  letter-spacing: 12px; text-transform: uppercase;
  text-align: center; margin: 0 0 8px;
  color: #f5fbff;
  text-indent: 12px;
  line-height: 1;
  text-shadow:
    0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.85),
    0 0 28px rgba(var(--theme-rgb, 79,195,247), 0.45),
    0 0 48px rgba(var(--theme-rgb, 79,195,247), 0.18);
}
.mm-subtitle {
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px; font-weight: 600;
  letter-spacing: 5px; text-transform: uppercase;
  text-align: center; color: #9ecfed;
  margin-bottom: 20px;
  text-indent: 5px;
  text-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.30);
}
/* Decorative divider between headline and menu — a hairline with a
   central neon diamond node (Tron circuit tap point). */
.mm-divider {
  position: relative;
  height: 1px;
  margin: 0 auto 26px;
  width: 72%;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(var(--theme-rgb, 79,195,247), 0.55) 20%,
    rgba(var(--theme-rgb, 79,195,247), 0.55) 80%,
    transparent 100%);
}
.mm-divider::after {
  content: "";
  position: absolute; top: 50%; left: 50%;
  width: 6px; height: 6px;
  transform: translate(-50%, -50%) rotate(45deg);
  background: rgb(var(--theme-rgb, 79,195,247));
  box-shadow:
    0 0 6px rgba(var(--theme-rgb, 79,195,247),1),
    0 0 14px rgba(var(--theme-rgb, 79,195,247),0.65);
}
/* Footer version tag — small, low-contrast, bottom of panel */
.mm-footer {
  font-family: 'Rajdhani', sans-serif;
  font-size: 10px; font-weight: 600;
  letter-spacing: 3px; text-transform: uppercase;
  text-align: center;
  color: rgba(159,207,237,0.50);
  margin-top: 22px;
  text-indent: 3px;
}
.mm-grid {
  display: flex; flex-direction: column; gap: 10px;
}
/* Section variant — slightly tighter spacing so each grouped
   block reads as one visual unit under its label. */
.mm-grid.mm-grid-section {
  gap: 8px;
  margin-bottom: 14px;
}
.mm-grid.mm-grid-section:last-of-type {
  margin-bottom: 4px;
}
/* Section label above each grid block — small caps Tron header
   that introduces what's grouped beneath. Theme-tinted so it
   tracks the active accent (purple/cyan/etc.) and gets the same
   neon-glow treatment as .mm-title — the title ribbon and the
   section labels read as a single chrome family. User spec:
   "the section headers should match the color of 'the game'
   and be neon highlighted". */
.mm-section-label {
  font-family: 'Rajdhani', sans-serif;
  font-size: 12px;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--theme-accent-bright, #f5fbff);
  margin: 6px 0 6px 2px;
  padding-left: 10px;
  border-left: 2px solid var(--theme-accent-bright, rgba(var(--theme-rgb, 79,195,247), 0.85));
  text-shadow:
    0 0 6px var(--theme-accent-bright, rgba(var(--theme-rgb, 79,195,247), 0.85)),
    0 0 14px var(--theme-glow-outer, rgba(var(--theme-rgb, 79,195,247), 0.45)),
    0 0 24px var(--theme-glow-inner, rgba(var(--theme-rgb, 79,195,247), 0.25));
  font-weight: 800;
}
.mm-section-label:first-of-type {
  margin-top: 4px;
}
.mm-option {
  position: relative;
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(var(--theme-rgb, 79,195,247), 0.06) 0%, rgba(0,0,0,0) 55%),
    #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  border-radius: 4px;
  padding: 14px 18px 14px 22px;
  cursor: pointer;
  color: #f5fbff;
  font-family: 'Rajdhani', sans-serif;
  display: flex; align-items: center; gap: 16px;
  text-align: left;
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s, background 0.2s, padding-left 0.2s;
  box-shadow:
    0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.18),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.05);
}
/* Left-edge accent bar — idle state is a thin 2px cyan vertical; on hover
   it brightens + the option shifts right so the bar reads as an active
   tab indicator. */
.mm-option::before {
  content: "";
  position: absolute;
  left: 0; top: 10%; bottom: 10%;
  width: 2px;
  background: rgba(var(--theme-rgb, 79,195,247), 0.60);
  box-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.55);
  transition: width 0.2s, background 0.2s, box-shadow 0.2s, top 0.2s, bottom 0.2s;
}
.mm-option:hover {
  transform: translateY(-1px);
  border-color: rgba(var(--theme-rgb, 79,195,247), 1);
  background:
    linear-gradient(90deg, rgba(var(--theme-rgb, 79,195,247), 0.12) 0%, rgba(0,0,0,0) 55%),
    rgba(var(--theme-rgb, 79,195,247), 0.04);
  padding-left: 26px;
  box-shadow:
    0 0 20px rgba(var(--theme-rgb, 79,195,247), 0.55),
    0 0 40px rgba(var(--theme-rgb, 79,195,247), 0.22),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.18);
}
.mm-option:hover::before {
  width: 3px;
  top: 0; bottom: 0;
  background: rgb(var(--theme-rgb, 79,195,247));
  box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247),1), 0 0 18px rgba(var(--theme-rgb, 79,195,247),0.55);
}
.mm-option:active {
  transform: translateY(0);
  box-shadow:
    0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.40),
    inset 0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.18);
}
.mm-option-icon {
  flex-shrink: 0;
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
}
/* Tron SVG icons — `stroke: currentColor` means the inherited cyan is
   already applied. The glow is layered via a drop-shadow filter so it
   composites on the GPU (cheaper than animating text-shadow). */
.mm-svg {
  width: 26px; height: 26px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  filter:
    drop-shadow(0 0 4px rgba(var(--theme-rgb, 79,195,247), 0.75))
    drop-shadow(0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.35));
  transition: transform 0.2s, filter 0.25s;
}
.mm-option:hover .mm-svg {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  filter:
    drop-shadow(0 0 5px rgba(var(--theme-rgb, 79,195,247), 1))
    drop-shadow(0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.55));
  transform: scale(1.08);
}
.mm-option-label {
  font-size: 16px; font-weight: 700;
  letter-spacing: 3px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.70);
}
.mm-option-sub {
  font-size: 11px; font-weight: 500;
  letter-spacing: 0.5px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white);
  line-height: 1.4;
  margin-top: 2px;
}

/* "Menu" back button shared by pre-match sub-screens (mode picker,
   stats, my decks, multiplayer, encyclopedia, match history, tutorial).
   Pinned to the VIEWPORT top-left via position:fixed so the corner
   placement is identical across all overlays — independent of how
   each panel handles its own padding/centering. Matches the Deck
   Builder's full-bleed MENU placement. User spec: "the menu bar
   should be where i drew it roughly in the top left corner just like
   the deck builder all 'menu' should be like this." */
/* Back button — positioned INSIDE the host panel's neon border at its
   top-left corner, matching the deck builder's MENU placement. The
   parent panel needs `position: relative` so this absolute pin anchors
   to the panel's top-left, not the viewport. `!important` on position
   is mandatory because .tron-fx (added at runtime by applyTronFx)
   sets position:relative on every Tron-decorated button, which would
   otherwise drop the button into normal flow.
   User feedback: "Want all menu buttons to look like the deck builders.
   Inside the dimensions of our neon border. Not outside of it." */
.mode-back, .stats-back, .md-back {
  position: absolute !important;
  top: 16px !important; left: 16px !important;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  padding: 6px 12px;
  border-radius: 3px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  cursor: pointer;
  transition: border-color 0.15s, box-shadow 0.15s;
  z-index: 20;  /* above panel content but contained within the panel */
}
/* Each host panel must establish a positioning context for its back
   button. Without this, position:absolute would attach to the nearest
   ancestor with position set (often the body or the overlay backdrop),
   breaking the "inside the panel border" placement. */
.mode-panel, .stats-panel, .md-panel, .encyc-panel,
.mh-panel, .mp-panel, .game-over-content {
  position: relative;
}
.mode-back:hover, .stats-back:hover, .md-back:hover {
  border-color: rgba(var(--theme-rgb, 79,195,247), 1);
  box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.40);
}

/* ============================================================
   MY DECKS OVERLAY (phase 4b) — saved-deck browser.
   ============================================================ */
.my-decks-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  display: flex; align-items: flex-start; justify-content: center;
  z-index: 212;
  background: #000000;
  overflow-y: auto;
}
.md-panel {
  max-width: 960px; width: 94%;
  padding: 60px 32px 40px;
  position: relative;
  font-family: 'Rajdhani', sans-serif;
}
.md-title {
  font-size: 26px; font-weight: 700;
  letter-spacing: 8px; text-transform: uppercase;
  color: #f5fbff;
  text-align: center;
  margin: 0 0 8px;
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.70);
}
.md-subtitle {
  font-size: 11px; font-weight: 600;
  letter-spacing: 3px; text-transform: uppercase;
  color: #8fc8ee;
  text-align: center;
  margin-bottom: 26px;
}
.md-empty {
  text-align: center;
  color: #667078;
  font-style: italic;
  padding: 40px 20px;
  font-size: 14px;
}
.md-new-btn {
  display: block;
  margin: 20px auto 0;
  background: #000;
  border: 1px solid rgba(46,204,113,0.85);
  color: #8ef2ad;
  padding: 10px 24px;
  border-radius: 3px;
  font-family: inherit;
  font-size: 11px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 0 10px rgba(46,204,113,0.35);
  transition: border-color 0.15s, box-shadow 0.15s, color 0.15s;
}
.md-new-btn:hover {
  border-color: rgba(46,204,113,1);
  box-shadow: 0 0 18px rgba(46,204,113,0.55);
  color: #b4f5c4;
}
.md-deck-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 14px;
}
.md-deck-card {
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.60);
  border-radius: 4px;
  padding: 14px 16px 12px;
  box-shadow:
    0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.22),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.08);
  display: flex; flex-direction: column;
  gap: 10px;
  min-height: 180px;
  position: relative;
}
.md-deck-card.md-deck-incomplete {
  border-color: rgba(231,76,60,0.55);
  box-shadow:
    0 0 12px rgba(231,76,60,0.18),
    inset 0 0 0 1px rgba(231,76,60,0.06);
}
.md-deck-badge {
  position: absolute; top: 10px; right: 10px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 9px; font-weight: 800;
  letter-spacing: 2px;
  padding: 3px 8px;
  border-radius: 3px;
  border: 1px solid transparent;
}
.md-badge-ready {
  color: #8ef2ad;
  border-color: rgba(46,204,113,0.75);
  background: rgba(46,204,113,0.08);
  text-shadow: 0 0 6px rgba(46,204,113,0.80);
}
.md-badge-incomplete {
  color: #ff8a7a;
  border-color: rgba(231,76,60,0.75);
  background: rgba(231,76,60,0.08);
  text-shadow: 0 0 6px rgba(231,76,60,0.80);
}
.md-action-btn.md-action-disabled {
  opacity: 0.35;
  cursor: not-allowed;
  pointer-events: none;
}
.md-deck-name {
  font-size: 14px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  text-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.55);
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.25);
}
.md-deck-counts {
  display: flex; gap: 12px;
  font-size: 11px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white);
  letter-spacing: 1px;
}
.md-deck-counts b {
  color: #ffe066; font-weight: 700;
  font-variant-numeric: tabular-nums;
  margin-right: 3px;
}
.md-deck-preview {
  flex: 1;
  font-size: 10px;
  color: #9fb5c7;
  line-height: 1.45;
  letter-spacing: 0.3px;
  min-height: 30px;
}
.md-deck-actions {
  display: flex; gap: 6px; flex-wrap: wrap;
}
.md-action-btn {
  flex: 1 1 auto;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  padding: 5px 8px;
  font-family: inherit;
  font-size: 9px; font-weight: 700;
  letter-spacing: 1.2px; text-transform: uppercase;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
  min-width: 58px;
}
.md-action-btn:hover { border-color: rgba(var(--theme-rgb, 79,195,247),1); box-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247),0.40); }
.md-action-btn.md-action-play {
  border-color: rgba(46,204,113,0.85); color: #8ef2ad;
}
.md-action-btn.md-action-play:hover { border-color: rgba(46,204,113,1); box-shadow: 0 0 10px rgba(46,204,113,0.50); color: #b4f5c4; }
.md-action-btn.md-action-delete {
  border-color: rgba(231,76,60,0.55); color: #f1948a;
}
.md-action-btn.md-action-delete:hover { border-color: rgba(231,76,60,1); box-shadow: 0 0 10px rgba(231,76,60,0.50); color: #ffb5ad; }

/* ============================================================
   STATS OVERLAY (phase 4d) — per-card performance dashboard.
   ============================================================ */
.stats-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  display: flex; align-items: flex-start; justify-content: center;
  z-index: 213;
  background: #000000;
  overflow-y: auto;
}
.stats-panel {
  max-width: 1280px; width: 96%;
  /* Apply the codex-style panel chrome so Stats reads as part of
     the same visual family. User direction May-1: "Make stats look
     harmonious with codex." Layered gradient wash + theme-aware
     border + dual-layer bloom. */
  margin: 24px auto;
  padding: 52px 28px 32px;
  position: relative;
  font-family: 'Rajdhani', sans-serif;
  background:
    linear-gradient(180deg, var(--theme-wash-05, rgba(79,195,247,0.05)) 0%, rgba(0,0,0,0) 42%),
    #000;
  border: 1px solid var(--theme-accent-ring, rgba(79,195,247,0.55));
  border-radius: 4px;
  box-shadow:
    0 0 32px var(--theme-glow-inner, rgba(79,195,247,0.30)),
    0 0 72px var(--theme-glow-outer, rgba(79,195,247,0.14)),
    inset 0 0 0 1px var(--theme-wash-08, rgba(79,195,247,0.08));
}
/* Tron corner brackets — same pattern codex uses for secondary
   panels. Two 14px L-shapes at top-left and bottom-right. */
.stats-panel::before,
.stats-panel::after {
  content: '';
  position: absolute;
  width: 14px; height: 14px;
  pointer-events: none;
  border: 0 solid var(--theme-accent-bright, rgba(79,195,247,0.95));
  filter: drop-shadow(0 0 5px var(--theme-glow-outer, rgba(79,195,247,0.65)));
}
.stats-panel::before {
  top: -1px; left: -1px;
  border-top-width: 2px;
  border-left-width: 2px;
}
.stats-panel::after {
  bottom: -1px; right: -1px;
  border-bottom-width: 2px;
  border-right-width: 2px;
}
.stats-title {
  font-size: 26px; font-weight: 700;
  letter-spacing: 8px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 5%, white);
  text-align: center;
  margin: 0 0 8px;
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.70);
}
.stats-subtitle {
  font-size: 11px; font-weight: 600;
  letter-spacing: 3px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  text-align: center;
  margin-bottom: 14px;
}

/* Sample-size summary row — 2-3 chips showing "My Games", "Sim Games"
   (+ seat split when sim data present). Each chip shows the count as
   the big number and the average rounds below. Reads as a glanceable
   sanity check before trusting individual card stats. */
.stats-summary {
  display: flex; justify-content: center;
  gap: 10px;
  margin-bottom: 22px;
  flex-wrap: wrap;
}
.stats-summary-chip {
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  border-radius: 4px;
  padding: 10px 22px 9px;
  min-width: 160px;
  text-align: center;
  box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.25), inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.08);
  font-family: 'Rajdhani', sans-serif;
}
.stats-summary-label {
  font-size: 9px; font-weight: 700;
  letter-spacing: 2.5px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  margin-bottom: 3px;
}
.stats-summary-value {
  font-size: 22px; font-weight: 700;
  color: #ffe066;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.3px;
  text-shadow: 0 0 6px rgba(255,215,0,0.45);
}
.stats-summary-sub {
  font-size: 10px; font-weight: 500;
  color: #8690a0;
  letter-spacing: 0.8px;
  margin-top: 3px;
}
.stats-empty {
  text-align: center;
  color: #667078;
  font-style: italic;
  padding: 40px 20px;
  font-size: 14px;
}
.stats-source-row {
  display: flex; gap: 6px; justify-content: center;
  margin-bottom: 14px;
}
.stats-source-btn {
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.45);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  padding: 6px 16px;
  font-family: inherit;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
}
.stats-source-btn:hover { border-color: rgba(var(--theme-rgb, 79,195,247), 0.85); color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white); }
.stats-source-active {
  background: rgba(var(--theme-rgb, 79,195,247), 0.12);
  border-color: rgba(var(--theme-rgb, 79,195,247), 1);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
/* Cards / Tricks view toggle — sits below the source toggle. Same chrome
   as the source buttons but wider + more visible so the view swap reads
   as a primary nav control. */
.stats-view-row {
  display: flex; gap: 6px; justify-content: center;
  margin-top: 10px; margin-bottom: 16px;
}
.stats-view-btn {
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  padding: 8px 22px;
  font-family: inherit;
  font-size: 11px; font-weight: 700;
  letter-spacing: 2.5px; text-transform: uppercase;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
}
.stats-view-btn:hover { border-color: rgba(var(--theme-rgb, 79,195,247), 0.85); color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white); }
.stats-view-active {
  background: rgba(var(--theme-rgb, 79,195,247), 0.15);
  border-color: rgba(var(--theme-rgb, 79,195,247), 1);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  box-shadow: 0 0 12px rgba(var(--theme-rgb, 79,195,247), 0.50);
}
/* Trick cost pip in the stats table — purple neon matching the trick
   card chrome throughout the game. Fully saturated amethyst border +
   double-halo glow, same spec as the card pip just swapped to purple. */
.stats-table .stats-cost.stats-cost-trick {
  border-color: rgba(155,89,182,1);
  color: #d7b3e6;
  box-shadow:
    0 0 8px rgba(155,89,182,0.65),
    0 0 16px rgba(155,89,182,0.30);
  text-shadow: 0 0 5px rgba(155,89,182,0.85);
}

/* AI weights panel — sits at the bottom of the stats screen. Collapsible
   so it doesn't dominate the view but is always one click away for
   auditing the heuristic. Groups mirror the logical sections of AI.WEIGHTS
   (draft / threat / defensive / tricks / lookahead). */
.ai-weights-panel {
  margin-top: 22px;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.35);
  border-radius: 4px;
  overflow: hidden;
}
.ai-weights-toggle {
  display: flex; align-items: center; gap: 10px;
  width: 100%; padding: 12px 16px;
  background: transparent;
  border: none;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  font-family: 'Rajdhani', sans-serif;
  font-size: 12px; font-weight: 700;
  letter-spacing: 2.5px; text-transform: uppercase;
  cursor: pointer;
  text-align: left;
  transition: background 0.15s, color 0.15s;
}
.ai-weights-toggle:hover { background: rgba(var(--theme-rgb, 79,195,247), 0.04); color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white); }
.ai-weights-caret {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  font-size: 10px;
  width: 10px; display: inline-block;
}
.ai-weights-hint {
  margin-left: auto;
  font-size: 10px;
  color: #667078;
  font-weight: 500;
  letter-spacing: 1px;
  text-transform: none;
}
.ai-weights-body {
  padding: 10px 16px 18px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 18px;
  border-top: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.20);
}
.ai-weight-group-title {
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.5px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  padding: 8px 0 6px;
  border-bottom: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.15);
  margin-bottom: 6px;
}
.ai-weight-list {
  display: flex; flex-direction: column;
  gap: 3px;
}
.ai-weight-row {
  display: flex; justify-content: space-between;
  align-items: baseline;
  padding: 4px 8px;
  background: rgba(var(--theme-rgb, 79,195,247), 0.04);
  border-radius: 3px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px;
  cursor: help;
}
.ai-weight-row:hover {
  background: rgba(var(--theme-rgb, 79,195,247), 0.10);
}
.ai-weight-label {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white);
  letter-spacing: 0.3px;
}
.ai-weight-value {
  color: #ffe066;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 4px rgba(255,215,0,0.35);
  margin-left: 10px;
}
.stats-actions-row {
  display: flex; gap: 8px; justify-content: center; align-items: center;
  margin-bottom: 18px;
  flex-wrap: wrap;
}
.stats-export-btn, .stats-reset-btn, .stats-reload-btn {
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  padding: 6px 14px;
  font-family: inherit;
  font-size: 10px; font-weight: 700;
  letter-spacing: 1.5px; text-transform: uppercase;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
}
.stats-export-btn:hover, .stats-reload-btn:hover { border-color: rgba(var(--theme-rgb, 79,195,247), 1); box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.40); }
.stats-reset-btn { border-color: rgba(231,76,60,0.55); color: #f1948a; }
.stats-reset-btn:hover { border-color: rgba(231,76,60,1); box-shadow: 0 0 10px rgba(231,76,60,0.45); color: #ffb5ad; }

/* Auto-flag banner (phase 4f) — headline summary across all cards. */
.stats-flag-banner {
  background: #000;
  border: 1px solid rgba(255,215,0,0.65);
  border-radius: 4px;
  padding: 12px 18px;
  margin-bottom: 18px;
  box-shadow:
    0 0 14px rgba(255,215,0,0.25),
    inset 0 0 0 1px rgba(255,215,0,0.10);
}
.stats-flag-title {
  font-size: 10px; font-weight: 700;
  letter-spacing: 3px; text-transform: uppercase;
  color: #ffe066;
  text-shadow: 0 0 6px rgba(255,215,0,0.60);
  margin-bottom: 8px;
}
.stats-flag-list {
  display: flex; gap: 10px; flex-wrap: wrap;
  font-size: 11px;
}
.stats-flag-item {
  background: rgba(255,255,255,0.03);
  padding: 4px 10px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,0.12);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 10%, white);
  letter-spacing: 0.5px;
}
.stats-flag-item.stats-flag-over {
  border-color: rgba(231,76,60,0.55);
  color: #ff8a7a;
}
.stats-flag-item.stats-flag-under {
  border-color: rgba(var(--theme-rgb, 79,195,247), 0.55);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
}

/* Definitions panel — always visible, 4-column grid above the table.
   Keeps the headline metrics self-documenting so no one has to guess
   what Impact Index / Contribution / MVP Rate mean. */

/* ==== Sim run history panel ==== */
.stats-hist-panel {
  background: rgba(0,0,0,0.55);
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.25);
  border-radius: 6px;
  padding: 12px 14px;
  margin: 12px 0;
}
.stats-hist-title {
  font-size: 13px;
  font-weight: 700;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 75%, white);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.stats-hist-count {
  font-weight: 400;
  font-size: 11px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 30%, #8a96a5);
  text-transform: none;
  letter-spacing: 0;
}
.stats-hist-runs {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
}
.stats-hist-run {
  flex: 0 0 auto;
  min-width: 130px;
  padding: 8px 10px;
  background: rgba(0,0,0,0.65);
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.30);
  border-radius: 4px;
  position: relative;
  font: 11px ui-monospace, Menlo, monospace;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 30%, white);
}
.stats-hist-run.stats-hist-balanced { border-color: rgba(100, 220, 100, 0.4); }
.stats-hist-run.stats-hist-biased   { border-color: rgba(220, 180, 100, 0.5); }
.stats-hist-latest {
  position: absolute;
  top: -7px;
  right: 6px;
  background: rgb(var(--theme-rgb, 79,195,247));
  color: #000;
  font-size: 9px;
  font-weight: 700;
  padding: 1px 5px;
  border-radius: 2px;
  letter-spacing: 0.08em;
}
.stats-hist-run-when { color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, #8a96a5); font-size: 10px; }
.stats-hist-run-games { color: #fff; font-weight: 600; font-size: 12px; margin-top: 2px; }
.stats-hist-run-split { margin-top: 3px; color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 60%, white); }

.stats-hist-movers {
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px dashed rgba(var(--theme-rgb, 79,195,247), 0.15);
}
.stats-hist-movers-title {
  font-size: 11px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 30%, #8a96a5);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 6px;
}
.stats-hist-movers-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 4px 10px;
}
.stats-hist-mover {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 6px;
  align-items: center;
  padding: 4px 8px;
  background: rgba(0,0,0,0.45);
  border-radius: 3px;
  font: 11px ui-monospace, Menlo, monospace;
  cursor: pointer;
  transition: background 80ms;
}
.stats-hist-mover:hover { background: rgba(var(--theme-rgb, 79,195,247), 0.10); }
.stats-hist-mover-name { color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 30%, white); font-weight: 600; }
.stats-hist-mover-delta { font-weight: 700; text-align: right; min-width: 55px; }
.stats-hist-mover-wr { color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 30%, #8a96a5); font-size: 10px; }
.stats-hist-mover.stats-hist-up   .stats-hist-mover-delta { color: #6c6; }
.stats-hist-mover.stats-hist-down .stats-hist-mover-delta { color: #d66; }

.stats-defs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 10px;
  margin-bottom: 18px;
  padding: 12px 14px;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.35);
  border-radius: 4px;
  box-shadow: inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.08);
}
.stats-def {
  display: flex; flex-direction: column; gap: 4px;
  padding: 2px 4px;
}
.stats-def-label {
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white);
  text-shadow: 0 0 5px rgba(var(--theme-rgb, 79,195,247), 0.55);
}
.stats-def-body {
  font-size: 11px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white);
  line-height: 1.45;
  letter-spacing: 0.2px;
}
.stats-def-body b {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 5%, white);
  font-weight: 700;
}
/* Formula row spans the full width at the bottom. Slightly dimmer —
   it's reference info, not a primary metric. */
.stats-def-formula {
  grid-column: 1 / -1;
  padding-top: 10px;
  margin-top: 4px;
  border-top: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.20);
}
.stats-def-formula .stats-def-label {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  text-shadow: 0 0 4px rgba(var(--theme-rgb, 79,195,247), 0.35);
}
.stats-def-formula .stats-def-body {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 25%, #8a96a5);
  font-size: 10.5px;
}

/* Stats table */
.stats-table-wrap { overflow-x: auto; }
.stats-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-family: 'Rajdhani', sans-serif;
  font-size: 11.5px;
}
.stats-table th, .stats-table td {
  padding: 7px 10px;
  text-align: left;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
/* Card/trick name cell — force single-line so cost pip + name + ATK/HP
   sit on the same row. Give it enough min-width to fit typical names +
   stats without truncation; the table has overflow-x:auto for edge cases. */
.stats-table .stats-card-name {
  white-space: nowrap;
  min-width: 260px;
}
.stats-table th {
  font-size: 9px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  cursor: pointer;
  user-select: none;
  background: #000;
  position: sticky; top: 0; z-index: 1;
  border-bottom: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.35);
}
.stats-table th:hover { color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white); }
.stats-table th.stats-sort-active { color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white); text-shadow: 0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.55); }
.stats-table tr { transition: background 0.1s; }
.stats-table tbody tr:hover { background: rgba(var(--theme-rgb, 79,195,247), 0.04); cursor: pointer; }
.stats-table td { color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 10%, white); letter-spacing: 0.3px; font-variant-numeric: tabular-nums; }
.stats-table .stats-card-name { font-weight: 700; letter-spacing: 0.8px; }
/* Rarity-neon name coloring — matches .card .card-name and the deck
   builder so the stats table reads as the same visual family. Default
   (no cost-class match) stays white for tokens / unknown names. */
.stats-name-text { margin-left: 8px; }
.stats-table tr.cost-0 .stats-name-text, .stats-table tr.cost-1 .stats-name-text,
.stats-table tr.cost-2 .stats-name-text, .stats-table tr.cost-3 .stats-name-text {
  color: #8ef2ad;
  text-shadow: 0 0 4px rgba(46,204,113,0.90), 0 0 10px rgba(46,204,113,0.40);
}
.stats-table tr.cost-4 .stats-name-text, .stats-table tr.cost-5 .stats-name-text,
.stats-table tr.cost-6 .stats-name-text {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 70%, white);
  text-shadow: 0 0 4px rgba(var(--theme-rgb, 79,195,247), 0.95), 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.45);
}
.stats-table tr.cost-7 .stats-name-text, .stats-table tr.cost-8 .stats-name-text {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 8%, white);
  text-shadow: 0 0 4px rgba(240,245,250,1), 0 0 10px rgba(240,245,250,0.55);
}
.stats-table tr.cost-9 .stats-name-text, .stats-table tr.cost-10 .stats-name-text {
  color: #ffe066;
  text-shadow: 0 0 4px rgba(255,215,0,1), 0 0 10px rgba(255,215,0,0.50);
}
/* Trick rows — purple neon name matching the trick card chrome. */
.stats-table tr.stats-trick-row .stats-name-text {
  color: #d7b3e6;
  text-shadow: 0 0 4px rgba(155,89,182,0.95), 0 0 10px rgba(155,89,182,0.45);
}
/* Inline ATK / HP stats next to the card name — neon green / neon red
   matching the on-board stat-atk / stat-hp orbs. */
.stats-atkhp {
  display: inline-flex; align-items: baseline; gap: 2px;
  margin-left: 10px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px; font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.3px;
}
.stats-atk {
  color: #7ee8a5;
  text-shadow: 0 0 4px rgba(46,204,113,0.95), 0 0 8px rgba(46,204,113,0.55);
}
.stats-hp {
  color: #f1948a;
  text-shadow: 0 0 4px rgba(231,76,60,1), 0 0 8px rgba(231,76,60,0.55);
}
.stats-slash { color: #6a7580; }
/* Low-sample rows stay dimmed — override rarity colors so noise rows
   don't draw the eye. */
.stats-table tr.stats-lowsample .stats-name-text { opacity: 0.55; text-shadow: none; }
.stats-table tr.stats-lowsample .stats-atk, .stats-table tr.stats-lowsample .stats-hp { opacity: 0.55; text-shadow: none; }
/* Card cost pip — legendary-gold neon. Full-saturation border, strong
   double-halo glow, matches the in-game `.card-cost` chrome so the
   stats table reads as the same visual family as the hand / board. */
.stats-table .stats-cost {
  display: inline-block;
  width: 22px; height: 22px; border-radius: 50%;
  background: #000;
  text-align: center; line-height: 20px;
  border: 1px solid currentColor;
  color: #ffe066;            /* default — overridden per-tier below */
  font-size: 11px; font-weight: 700;
  font-family: 'Rajdhani', sans-serif;
  font-variant-numeric: tabular-nums;
  margin-right: 8px;
  box-shadow:
    0 0 8px color-mix(in srgb, currentColor 65%, transparent),
    0 0 16px color-mix(in srgb, currentColor 30%, transparent);
  text-shadow: 0 0 5px currentColor;
  vertical-align: middle;
}
/* Rarity-tier coloring for the cost orb — matches the in-game card
   diamond chrome. The parent <tr> carries .cost-N (added via
   getCostClass) so this selector tints the inner orb to match.
   User report: "the energy orbs need to be the diamond rarity
   themed." Tiers:
     0-3  → green   (common)
     4-6  → cyan    (uncommon)
     7-8  → silver  (rare)
     9-10 → gold    (legendary) — already the default */
.stats-table tr.cost-1 .stats-cost,
.stats-table tr.cost-2 .stats-cost,
.stats-table tr.cost-3 .stats-cost {
  color: #6ef58b;            /* green */
}
.stats-table tr.cost-4 .stats-cost,
.stats-table tr.cost-5 .stats-cost,
.stats-table tr.cost-6 .stats-cost {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 75%, white);            /* cyan */
}
.stats-table tr.cost-7 .stats-cost,
.stats-table tr.cost-8 .stats-cost {
  color: #d8e0eb;            /* silver */
}
.stats-table tr.cost-9 .stats-cost,
.stats-table tr.cost-10 .stats-cost {
  color: #ffe066;            /* gold (legendary) */
}
.stats-wr-over   { color: #ff8a7a; text-shadow: 0 0 4px rgba(231,76,60,0.50); }
.stats-wr-under  { color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white); text-shadow: 0 0 4px rgba(var(--theme-rgb, 79,195,247), 0.50); }
.stats-wr-ok     { color: #b4f5c4; }
.stats-ci        { color: #8690a0; font-size: 10px; margin-left: 4px; }
.stats-lowsample { opacity: 0.55; }
.stats-lowsample td { color: #8690a0; }

/* Detail modal (card detail drill-in). */
.stats-detail-backdrop {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.80);
  z-index: 220;
  display: flex; align-items: center; justify-content: center;
}
.stats-detail-panel {
  max-width: 560px; width: 92%;
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.70);
  border-radius: 4px;
  padding: 24px 26px 22px;
  box-shadow:
    0 0 22px rgba(var(--theme-rgb, 79,195,247), 0.45),
    inset 0 0 0 1px rgba(var(--theme-rgb, 79,195,247), 0.10);
}
.stats-detail-close {
  float: right;
  background: none; border: none;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white); cursor: pointer;
  font-size: 20px; padding: 0; line-height: 1;
}
.stats-detail-name {
  font-size: 18px; font-weight: 700;
  letter-spacing: 3px; text-transform: uppercase;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 5%, white);
  margin-bottom: 4px;
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.60);
}
.stats-detail-meta {
  font-size: 11px;
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 25%, #8a96a5);
  letter-spacing: 1px;
  margin-bottom: 18px;
}
.stats-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 16px;
  font-size: 12px;
}
.stats-detail-row {
  display: flex; justify-content: space-between;
  padding: 5px 10px;
  background: rgba(var(--theme-rgb, 79,195,247), 0.05);
  border-radius: 3px;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.18);
}
.stats-detail-label {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  font-size: 10px; font-weight: 700;
  letter-spacing: 1px; text-transform: uppercase;
}
.stats-detail-value {
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 10%, white);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* ============================================================
   DECK BUILDER OVERLAY (phase 3) — full-screen build surface.
   Layout: header row (back + title + presets) → body grid (two
   columns) → footer (save / load / start).
   Chrome matches the rest of the game: Tron capsule + cyan
   edges, rarity-tinted card chips by cost class.
   ============================================================ */
.deckbuilder-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  display: flex; align-items: stretch; justify-content: center;
  z-index: 205;
  background: #000000;
  overflow: hidden;
}
.db-panel {
  width: 100%;
  max-width: 1440px;
  padding: 18px 24px 16px;
  display: flex; flex-direction: column;
  box-sizing: border-box;
  font-family: 'Rajdhani', sans-serif;
}

/* ---- Header row ---- */
.db-header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 20px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.35);
}
.db-title {
  font-size: 22px; font-weight: 700;
  letter-spacing: 6px; text-transform: uppercase;
  color: #f5fbff; margin: 0;
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79,195,247), 0.70);
  text-align: center;
}
.db-back {
  background: #000; border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.60);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 65%, white); padding: 6px 14px; border-radius: 3px;
  font-family: inherit; font-size: 11px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  cursor: pointer;
  transition: border-color 0.15s, box-shadow 0.15s, color 0.15s;
}
.db-back:hover { border-color: rgba(var(--theme-rgb, 79,195,247),1); color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white); box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247),0.45); }
.db-presets { display: flex; gap: 8px; justify-self: end; }
.db-preset {
  background: #000; border: 1px solid rgba(155,89,182,0.55);
  color: #d7b3e6; padding: 6px 12px; border-radius: 3px;
  font-family: inherit; font-size: 10px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  cursor: pointer;
  transition: border-color 0.15s, box-shadow 0.15s, color 0.15s;
}
.db-preset:hover { border-color: rgba(155,89,182,1); color: #ecd3f6; box-shadow: 0 0 10px rgba(155,89,182,0.45); }
.db-preset-active {
  border-color: rgba(155,89,182,1); color: #ecd3f6;
  box-shadow: 0 0 12px rgba(155,89,182,0.60), inset 0 0 0 1px rgba(155,89,182,0.30);
}

/* ---- Body: two-column split ---- */
.db-body {
  /* Horizontal-layered layout (user spec): deck strip stacks ABOVE
     the collection. Column layout guarantees the children stack
     top-to-bottom; each row takes the full panel width. */
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
  padding-top: 14px;
  gap: 0;
}
.db-left, .db-right {
  display: flex; flex-direction: column;
  min-height: 0;
}

/* ---- Tabs + cost filter ---- */
.db-tabs { display: flex; gap: 6px; margin-bottom: 10px; }
.db-tab {
  background: #000; border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.40);
  color: #8fc8ee; padding: 8px 20px; border-radius: 3px;
  font-family: inherit; font-size: 11px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  cursor: pointer;
  transition: all 0.15s;
}
.db-tab:hover { border-color: rgba(var(--theme-rgb, 79,195,247),0.80); color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white); }
.db-filter-active {
  background: rgba(var(--theme-rgb, 79,195,247),0.12); color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 50%, white);
  border-color: rgba(var(--theme-rgb, 79,195,247),1);
  box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247),0.45);
}
.db-cost-row { display: flex; gap: 4px; margin-bottom: 12px; flex-wrap: wrap; }
.db-cost-chip {
  background: #000; border: 1px solid rgba(255,255,255,0.25);
  color: #a0aab5; padding: 4px 10px; border-radius: 3px;
  font-family: inherit; font-size: 10px; font-weight: 700;
  letter-spacing: 1px; text-transform: uppercase;
  cursor: pointer;
  transition: all 0.15s;
}
.db-cost-chip:hover { border-color: rgba(255,255,255,0.55); color: #e8f5ff; }
.db-cost-active {
  background: rgba(255,255,255,0.06); color: #f5fbff;
  border-color: rgba(255,255,255,0.80);
}

/* ---- Card grid ---- */
.db-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
  gap: 8px;
  overflow-y: auto;
  padding-right: 6px;
  flex: 1 1 auto;
  align-content: start;
}
.db-grid::-webkit-scrollbar { width: 6px; }
.db-grid::-webkit-scrollbar-thumb { background: rgba(var(--theme-rgb, 79,195,247), 0.30); border-radius: 3px; }
.db-grid-item {
  background: #000;
  border: 1px solid rgba(255,255,255,0.20);
  border-radius: 3px;
  /* Three anchored regions:
       - Left: shrunk cost diamond (absolute, top-left)
       - Center: name + stats (flex-column), count chip pinned bottom-left
       - Right: status badges in a vertical column from top-right,
                wrapping ONE column leftward for up to 6 total (3 × 2)
     Right padding reserves the badge column's width. */
  padding: 10px 90px 24px 18px;
  cursor: pointer;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  min-height: 72px;
  overflow: hidden;
  transition: border-color 0.15s, box-shadow 0.15s, transform 0.1s;
}
.db-grid-main {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}
.db-grid-info {
  display: flex; flex-direction: column; gap: 3px;
  min-width: 0; /* allow name to shrink inside the flex row */
  flex: 1 1 auto;
}
.db-grid-item:hover { transform: translateY(-1px); }
/* Cost badge — diamond pip that mirrors the in-game `.card-cost`
   chrome. Rotated-square backdrop with an upright numeral on top,
   tinted per rarity tier. Absolutely-positioned in the top-left
   corner, hanging slightly over the card's edge like the board
   cards do. */
.db-grid-cost {
  /* Sized + positioned to fit ENTIRELY inside .db-grid-item, which has
     `overflow: hidden`. The earlier negative offset was hanging the
     rotated square off the corner where the parent clipped it.
     A 14x14 box rotated 45° has a ~20px diagonal, so 2px from the
     edge keeps the whole diamond visible. User spec: "the energy
     diamond is cut off — make it a little smaller to fit". */
  position: absolute; top: 2px; left: 2px;
  width: 14px; height: 14px;
  background: transparent;
  border: none;
  display: flex; align-items: center; justify-content: center;
  font-size: 9px; font-weight: 700;
  font-family: 'Rajdhani', sans-serif;
  font-variant-numeric: tabular-nums;
  z-index: 2;
}
.db-grid-cost::before {
  content: '';
  position: absolute; inset: 0;
  background: #000;
  border: 1px solid currentColor;
  transform: rotate(45deg);
  box-shadow:
    0 0 10px color-mix(in srgb, currentColor 85%, transparent),
    0 0 22px color-mix(in srgb, currentColor 40%, transparent);
  z-index: -1;
}
.db-grid-name {
  font-size: 11.5px; font-weight: 700;
  letter-spacing: 0.6px;
  color: #e8f5ff;
  line-height: 1.2;
}
/* Name color by rarity tier — mirrors .draft-card.cost-* .card-name so
   the deck-builder card name reads the same rarity signal as the draft /
   in-hand / on-board versions of the card. */
.db-grid-item.cost-0 .db-grid-name, .db-grid-item.cost-1 .db-grid-name,
.db-grid-item.cost-2 .db-grid-name, .db-grid-item.cost-3 .db-grid-name {
  color: #8ef2ad;
  text-shadow:
    0 0 4px rgba(46,204,113,0.90),
    0 0 10px rgba(46,204,113,0.40);
}
.db-grid-item.cost-4 .db-grid-name, .db-grid-item.cost-5 .db-grid-name,
.db-grid-item.cost-6 .db-grid-name {
  color: #9adcff;
  text-shadow:
    0 0 4px rgba(79,195,247,0.95),
    0 0 10px rgba(79,195,247,0.45);
}
.db-grid-item.cost-7 .db-grid-name, .db-grid-item.cost-8 .db-grid-name {
  color: #f4f8fd;
  text-shadow:
    0 0 4px rgba(240,245,250,1),
    0 0 10px rgba(240,245,250,0.55);
}
.db-grid-item.cost-9 .db-grid-name, .db-grid-item.cost-10 .db-grid-name {
  color: #ffe066;
  text-shadow:
    0 0 4px rgba(255,215,0,1),
    0 0 10px rgba(255,215,0,0.50);
}
/* Mirror the rarity-neon name on the deck panel rows too. */
.db-deck-row.cost-0 .db-deck-name, .db-deck-row.cost-1 .db-deck-name,
.db-deck-row.cost-2 .db-deck-name, .db-deck-row.cost-3 .db-deck-name {
  color: #8ef2ad;
  text-shadow: 0 0 4px rgba(46,204,113,0.75);
}
.db-deck-row.cost-4 .db-deck-name, .db-deck-row.cost-5 .db-deck-name,
.db-deck-row.cost-6 .db-deck-name {
  color: #9adcff;
  text-shadow: 0 0 4px rgba(79,195,247,0.75);
}
.db-deck-row.cost-7 .db-deck-name, .db-deck-row.cost-8 .db-deck-name {
  color: #f4f8fd;
  text-shadow: 0 0 4px rgba(240,245,250,0.85);
}
.db-deck-row.cost-9 .db-deck-name, .db-deck-row.cost-10 .db-deck-name {
  color: #ffe066;
  text-shadow: 0 0 4px rgba(255,215,0,0.80);
}
/* Stat row — neon green ATK / neon red HP, matching the board's
   .stat-atk / .stat-hp palette so the numbers read as the same kind of
   values even outside an actual stat orb. */
.db-grid-stat-row {
  display: inline-flex; align-items: baseline; gap: 3px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 12px; font-weight: 700;
  letter-spacing: 0.5px;
  font-variant-numeric: tabular-nums;
}
.db-grid-atk {
  color: #7ee8a5;
  text-shadow: 0 0 4px rgba(46,204,113,0.95), 0 0 8px rgba(46,204,113,0.55);
}
.db-grid-hp {
  color: #f1948a;
  text-shadow: 0 0 4px rgba(231,76,60,1), 0 0 8px rgba(231,76,60,0.6);
}
.db-grid-slash { color: #6a7580; }
/* Ability badges — vertical column pinned to the top-right corner
   of the card. Stacks downward, wraps ONE column leftward at 3 badges,
   for a max of 6 badges per card (3 tall × 2 wide). User spec: option
   (b) — "start top-right, work left, only 1 over". */
.db-grid-abilities {
  position: absolute;
  top: 6px; right: 6px;
  display: flex;
  flex-direction: column-reverse;         /* new items push up-left when they wrap */
  flex-wrap: wrap-reverse;                 /* wrap leftward, not downward */
  gap: 3px;
  align-items: flex-end;                   /* right-edge anchored */
  max-height: 64px;                        /* ~3 rows of badges */
  max-width: 82px;                         /* ~2 columns */
  z-index: 2;
}
.db-grid-abilities .status-badge {
  font-size: 8.5px; padding: 1px 5px; letter-spacing: 0.5px;
  max-width: 82px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.db-grid-count {
  /* Bottom-LEFT corner, UNDER the ATK/HP stats row — keeps it out of
     the right-side badge column and puts the quantity close to the
     stats it modifies. User spec: "grid count bottom left under the
     health and damage". */
  position: absolute; bottom: 6px; left: 14px;
  font-size: 10px; font-weight: 700;
  letter-spacing: 0.5px;
  color: rgb(var(--theme-rgb, 79,195,247));
  padding: 2px 6px;
  background: rgba(var(--theme-rgb, 79,195,247), 0.15);
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.50);
  border-radius: 10px;
  z-index: 2;
}
.db-grid-count-max {
  color: #ffe066;
  background: rgba(255,215,0,0.15);
  border-color: rgba(255,215,0,0.70);
}
.db-grid-item-disabled { opacity: 0.40; cursor: not-allowed; }
.db-grid-item-disabled:hover { transform: none; }

/* Rarity-tint cost chip + border by cost tier. Mirrors the in-game
   rarity palette (green common, cyan uncommon, silver rare, gold
   legendary). We only set `color` on the .db-grid-cost here — the
   diamond's border + glow reads `currentColor`, so the whole pip
   tints from a single property. Border on the CARD stays so the
   whole tile outline reads as the rarity tier. */
.db-grid-item.cost-0, .db-grid-item.cost-1, .db-grid-item.cost-2, .db-grid-item.cost-3 {
  border-color: rgba(46,204,113,0.60);
}
.db-grid-item.cost-0 .db-grid-cost, .db-grid-item.cost-1 .db-grid-cost,
.db-grid-item.cost-2 .db-grid-cost, .db-grid-item.cost-3 .db-grid-cost {
  color: #7ee8a5;
  text-shadow: 0 0 4px rgba(46,204,113,0.85), 0 0 10px rgba(46,204,113,0.40);
}
.db-grid-item.cost-4, .db-grid-item.cost-5, .db-grid-item.cost-6 {
  border-color: rgba(79,195,247,0.60);
}
.db-grid-item.cost-4 .db-grid-cost, .db-grid-item.cost-5 .db-grid-cost, .db-grid-item.cost-6 .db-grid-cost {
  color: #9adcff;
  text-shadow: 0 0 4px rgba(79,195,247,0.85), 0 0 10px rgba(79,195,247,0.40);
}
.db-grid-item.cost-7, .db-grid-item.cost-8 {
  border-color: rgba(240,245,250,0.70);
}
.db-grid-item.cost-7 .db-grid-cost, .db-grid-item.cost-8 .db-grid-cost {
  color: #f4f8fd;
  text-shadow: 0 0 4px rgba(240,245,250,0.95), 0 0 10px rgba(240,245,250,0.50);
}
.db-grid-item.cost-9, .db-grid-item.cost-10 {
  border-color: rgba(255,215,0,0.70);
}
.db-grid-item.cost-9 .db-grid-cost, .db-grid-item.cost-10 .db-grid-cost {
  color: #ffe066;
  text-shadow: 0 0 4px rgba(255,215,0,0.95), 0 0 10px rgba(255,215,0,0.55);
}

/* ---- Right pane: deck panel ---- */
.db-meters { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 14px; }
.db-meter {
  background: #000;
  border: 1px solid rgba(255,255,255,0.35);
  border-radius: 3px;
  padding: 10px 14px;
  display: flex; align-items: baseline; gap: 10px;
  transition: border-color 0.2s, box-shadow 0.2s, color 0.2s;
}
.db-meter-label {
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  color: #a0aab5;
}
.db-meter-value {
  font-size: 18px; font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #e8f5ff;
  letter-spacing: 0.5px;
}
.db-meter-ok {
  border-color: rgba(46,204,113,0.85);
  box-shadow: 0 0 10px rgba(46,204,113,0.40), inset 0 0 0 1px rgba(46,204,113,0.15);
}
.db-meter-ok .db-meter-value { color: #8ef2ad; text-shadow: 0 0 6px rgba(46,204,113,0.55); }
.db-meter-bad {
  border-color: rgba(231,76,60,0.85);
  box-shadow: 0 0 10px rgba(231,76,60,0.40);
}
.db-meter-bad .db-meter-value { color: #ff8a7a; }

.db-deck-section { margin-bottom: 14px; display: flex; flex-direction: column; min-height: 0; }
.db-deck-heading {
  font-size: 10px; font-weight: 700;
  letter-spacing: 3px; text-transform: uppercase;
  /* Theme-tinted heading + underline — mirrors the neon "section
     title" look used in the Settings modal (same CSS pattern). Was
     hardcoded to a washed blue that never responded to theme
     changes. */
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 35%, white);
  text-shadow:
    0 0 6px rgba(var(--theme-rgb, 79,195,247), 0.65),
    0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.30);
  padding: 6px 4px;
  border-bottom: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.35);
  margin-bottom: 4px;
}
.db-deck-list {
  max-height: 230px;
  overflow-y: auto;
  display: flex; flex-direction: column; gap: 4px;
  padding-right: 4px;
}
.db-deck-list::-webkit-scrollbar { width: 6px; }
.db-deck-list::-webkit-scrollbar-thumb { background: rgba(var(--theme-rgb, 79,195,247), 0.30); border-radius: 3px; }
.db-deck-empty {
  color: #667078; font-size: 11px; font-style: italic;
  padding: 6px 4px;
}
.db-deck-row {
  background: #000;
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 3px;
  padding: 5px 10px;
  display: grid;
  grid-template-columns: 22px 1fr auto auto;
  gap: 8px;
  align-items: center;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.db-deck-row:hover {
  border-color: rgba(231,76,60,0.80);
  background: rgba(231,76,60,0.06);
}
.db-deck-cost {
  text-align: center;
  font-size: 11px; font-weight: 700;
  color: #e8f5ff;
  font-variant-numeric: tabular-nums;
}
.db-deck-name {
  font-size: 11.5px; font-weight: 600;
  color: #e8f5ff;
  letter-spacing: 0.4px;
}
.db-deck-stats {
  display: inline-flex; align-items: baseline; gap: 2px;
  font-size: 11px; font-weight: 700;
  font-family: 'Rajdhani', sans-serif;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.3px;
}
.db-deck-atk {
  color: #7ee8a5;
  text-shadow: 0 0 4px rgba(46,204,113,0.90), 0 0 8px rgba(46,204,113,0.45);
}
.db-deck-hp {
  color: #f1948a;
  text-shadow: 0 0 4px rgba(231,76,60,0.95), 0 0 8px rgba(231,76,60,0.50);
}
.db-deck-slash { color: #6a7580; }
.db-deck-count {
  font-size: 10px; font-weight: 700;
  color: rgb(var(--theme-rgb, 79,195,247));
  padding: 2px 7px;
  background: rgba(var(--theme-rgb, 79,195,247), 0.15);
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.50);
  border-radius: 10px;
}
.db-deck-count-max {
  color: #ffe066;
  background: rgba(255,215,0,0.15);
  border-color: rgba(255,215,0,0.70);
}
/* Rarity tint on deck rows — matches the grid palette. */
.db-deck-row.cost-0, .db-deck-row.cost-1, .db-deck-row.cost-2, .db-deck-row.cost-3 { border-color: rgba(46,204,113,0.50); }
.db-deck-row.cost-4, .db-deck-row.cost-5, .db-deck-row.cost-6 { border-color: rgba(79,195,247,0.50); }
.db-deck-row.cost-7, .db-deck-row.cost-8 { border-color: rgba(240,245,250,0.60); }
.db-deck-row.cost-9, .db-deck-row.cost-10 { border-color: rgba(255,215,0,0.70); }

/* ---- Footer: save / load / start ---- */
.db-footer {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 14px;
  align-items: center;
  padding-top: 14px;
  border-top: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.35);
  margin-top: 10px;
}
.db-footer-left { display: flex; gap: 8px; align-items: center; }
.db-footer-center { display: flex; gap: 8px; align-items: center; justify-content: center; }
.db-footer-right { display: flex; gap: 8px; align-items: center; justify-content: flex-end; }
.db-footer-empty { font-size: 11px; color: #667078; font-style: italic; }
.db-save-name, .db-load-select {
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.55);
  color: #e8f5ff;
  padding: 7px 10px;
  font-family: inherit;
  font-size: 12px;
  border-radius: 3px;
  letter-spacing: 0.5px;
  width: 160px;
}
.db-save-name:focus, .db-load-select:focus {
  outline: none;
  border-color: rgba(var(--theme-rgb, 79,195,247), 1);
  box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.40);
}
/* ============================================================
   MATCH HISTORY — rolling list of last N matches, accessible from
   the main menu. Mirrors the mm-panel corner-bracket chrome so it
   reads as a first-class screen, not a grafted-on panel.
   ============================================================ */
.match-history-overlay {
  position: fixed; inset: 0;
  /* Stacked above main-menu-overlay (z-index 215) so opening from the
     main menu actually shows this panel instead of landing under it. */
  z-index: 250;
  background: #000;
  display: flex; align-items: center; justify-content: center;
  padding: 24px;
  overflow: auto;
}
.mh-panel {
  position: relative;
  max-width: 760px; width: 100%;
  padding: 48px 36px 32px;
  background:
    linear-gradient(180deg, var(--theme-wash-05, rgba(79,195,247,0.05)) 0%, rgba(0,0,0,0) 40%),
    #000;
  border: 1px solid var(--theme-accent-ring, rgba(79,195,247,0.55));
  border-radius: 4px;
  box-shadow:
    0 0 32px var(--theme-glow-inner, rgba(79,195,247,0.30)),
    0 0 72px var(--theme-glow-outer, rgba(79,195,247,0.14)),
    inset 0 0 0 1px var(--theme-wash-08, rgba(79,195,247,0.08));
  font-family: 'Rajdhani', sans-serif;
}
.mh-panel::before, .mh-panel::after {
  content: ""; position: absolute; width: 16px; height: 16px;
  pointer-events: none;
}
.mh-panel::before {
  top: -1px; left: -1px;
  border-top: 2px solid var(--theme-accent-bright, #4fc3f7);
  border-left: 2px solid var(--theme-accent-bright, #4fc3f7);
  filter: drop-shadow(0 0 6px var(--theme-glow-outer, rgba(79,195,247,0.75)));
}
.mh-panel::after {
  bottom: -1px; right: -1px;
  border-bottom: 2px solid var(--theme-accent-bright, #4fc3f7);
  border-right: 2px solid var(--theme-accent-bright, #4fc3f7);
  filter: drop-shadow(0 0 6px var(--theme-glow-outer, rgba(79,195,247,0.75)));
}
.mh-title {
  font-size: 32px; font-weight: 700;
  letter-spacing: 8px; text-transform: uppercase;
  text-align: center; margin: 0 0 4px;
  color: #f5fbff;
  text-shadow:
    0 0 10px var(--theme-accent-bright, rgba(79,195,247,0.85)),
    0 0 28px var(--theme-glow-outer, rgba(79,195,247,0.45));
}
.mh-sub {
  font-size: 10px; font-weight: 600;
  letter-spacing: 4px; text-transform: uppercase;
  text-align: center; color: color-mix(in srgb, var(--theme-accent, rgb(79,195,247)) 30%, #9ecfed);
  margin-bottom: 20px;
}
.mh-list { display: flex; flex-direction: column; gap: 8px; margin-bottom: 18px; }

/* Archetype breakdown panel — surfaces win rate per-matchup above
   the match list. Reads at a glance: green = strong matchup, gold =
   even, red = needs work. */
.mh-arch-panel {
  margin: 0 0 22px;
  padding: 14px 16px;
  background: rgba(0, 0, 0, 0.65);
  border: 1px solid var(--theme-accent-edge, rgba(79, 195, 247, 0.30));
  border-radius: 4px;
}
.mh-arch-title {
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--theme-accent, rgb(79,195,247)) 30%, #9ecfed);
  margin-bottom: 10px;
}
.mh-arch-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 18px;
}
.mh-arch-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 12px;
  align-items: center;
  padding: 6px 10px;
  background: rgba(0, 0, 0, 0.45);
  border-left: 2px solid var(--theme-accent-edge, rgba(79, 195, 247, 0.30));
  border-radius: 2px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 12px;
}
.mh-arch-name {
  color: #e8f0f8;
  letter-spacing: 0.5px;
}
.mh-arch-record {
  font-variant-numeric: tabular-nums;
  color: #9ecfed;
  letter-spacing: 1px;
}
.mh-arch-pct {
  font-weight: 800;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.5px;
}
.mh-arch-strong { border-left-color: rgba(46, 204, 113, 0.85); }
.mh-arch-strong .mh-arch-pct { color: #8ef2ad; text-shadow: 0 0 4px rgba(46, 204, 113, 0.55); }
.mh-arch-even   { border-left-color: rgba(255, 215, 0, 0.85); }
.mh-arch-even   .mh-arch-pct { color: #ffd95e; text-shadow: 0 0 4px rgba(255, 215, 0, 0.45); }
.mh-arch-weak   { border-left-color: rgba(231, 76, 60, 0.85); }
.mh-arch-weak   .mh-arch-pct { color: #ff8a7a; text-shadow: 0 0 4px rgba(231, 76, 60, 0.55); }
@media (max-width: 640px) {
  .mh-arch-list { grid-template-columns: 1fr; }
}
.mh-empty {
  text-align: center; padding: 36px 16px;
  color: color-mix(in srgb, var(--theme-accent, rgb(79,195,247)) 30%, #667078);
  font-style: italic; font-size: 13px;
  border: 1px dashed var(--theme-accent-edge, rgba(79,195,247,0.30));
  border-radius: 4px;
}
.mh-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1.4fr;
  gap: 16px; align-items: center;
  padding: 12px 16px;
  background: rgba(0,0,0,0.65);
  border: 1px solid var(--theme-accent-edge, rgba(79,195,247,0.30));
  border-radius: 4px;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.mh-row:hover { border-color: var(--theme-accent-bright, rgba(79,195,247,0.80)); }
.mh-row.mh-win    { border-left: 3px solid rgba(46,204,113,0.85); }
.mh-row.mh-loss   { border-left: 3px solid rgba(231,76,60,0.85); }
.mh-row.mh-draw   { border-left: 3px solid rgba(255,255,255,0.40); }
.mh-verdict {
  font-size: 14px; font-weight: 800;
  letter-spacing: 3px; text-transform: uppercase;
}
.mh-row.mh-win  .mh-verdict { color: #8ef2ad; text-shadow: 0 0 6px rgba(46,204,113,0.75); }
.mh-row.mh-loss .mh-verdict { color: #ff8a7a; text-shadow: 0 0 6px rgba(231,76,60,0.75); }
.mh-row.mh-draw .mh-verdict { color: #e8f0f8; }
.mh-meta {
  font-size: 10px; letter-spacing: 1px; text-transform: uppercase;
  color: #7a8a98; margin-top: 2px;
}
.mh-row-mid { text-align: center; }
.mh-hp {
  font-family: 'Rajdhani', sans-serif;
  font-size: 18px; font-weight: 700;
  letter-spacing: 1px;
}
.mh-hp-player { color: #8ef2ad; }
.mh-hp-ai     { color: #ff8a7a; }
.mh-hp-sep    { color: #6a7580; margin: 0 4px; font-weight: 400; }
.mh-hp-label {
  font-size: 9px; letter-spacing: 2px; text-transform: uppercase;
  color: #7a8a98;
}
.mh-row-right { text-align: right; }
.mh-mvp-label {
  font-size: 9px; letter-spacing: 2px; text-transform: uppercase;
  color: #7a8a98;
}
.mh-mvp-name {
  font-size: 13px; font-weight: 700;
  color: color-mix(in srgb, var(--theme-accent, rgb(79,195,247)) 30%, white);
}
.mh-actions { display: flex; justify-content: center; }
.mh-clear-btn {
  padding: 8px 18px;
  background: #000;
  border: 1px solid rgba(231,76,60,0.60);
  color: #ff8a7a;
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  border-radius: 3px; cursor: pointer;
  transition: all 0.15s;
}
.mh-clear-btn:hover {
  border-color: rgba(231,76,60,1);
  box-shadow: 0 0 10px rgba(231,76,60,0.45);
  color: #ffb5ad;
}
@container (max-width: 640px) {
  .mh-panel { padding: 40px 20px 24px; }
  .mh-title { font-size: 24px; letter-spacing: 5px; }
  .mh-row { grid-template-columns: 1fr; gap: 6px; }
  .mh-row-mid, .mh-row-right { text-align: left; }
}

/* ============================================================
   MULTIPLAYER LOBBY — re-skins .mh-panel with a 4-letter code
   display, tabs, and a connection-status card. Uses the same
   chrome (corner brackets, neon ring) as match-history so it
   visually slots into the menu surface without bespoke chrome.
   ============================================================ */
.multiplayer-overlay {
  position: fixed; inset: 0;
  z-index: 250;
  background: #000;
  display: flex; align-items: center; justify-content: center;
  padding: 24px;
  overflow: auto;
}
.mp-panel { max-width: 480px; }
.mp-tabs {
  display: flex; gap: 0;
  margin: 18px 0 22px;
  border: 1px solid var(--theme-accent-edge, rgba(79,195,247,0.30));
  border-radius: 4px;
  overflow: hidden;
}
.mp-tab {
  flex: 1;
  padding: 10px 16px;
  background: rgba(0,0,0,0.65);
  border: 0;
  color: color-mix(in srgb, var(--theme-accent, rgb(79,195,247)) 30%, #9ecfed);
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px; font-weight: 700;
  letter-spacing: 3px; text-transform: uppercase;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.mp-tab:hover { color: #f5fbff; background: rgba(79,195,247,0.08); }
.mp-tab-active {
  background: var(--theme-wash-08, rgba(79,195,247,0.10));
  color: #f5fbff;
  box-shadow: inset 0 -2px 0 0 var(--theme-accent-bright, #4fc3f7);
}
.mp-pane {
  display: flex; flex-direction: column; align-items: center;
  gap: 14px;
  padding: 18px 12px 6px;
}
.mp-pane-status { gap: 18px; padding-top: 10px; }
.mp-explainer {
  font-size: 13px; line-height: 1.5;
  color: color-mix(in srgb, var(--theme-accent, rgb(79,195,247)) 25%, #c4d6e0);
  text-align: center;
}
.mp-explainer b { color: #f5fbff; font-weight: 700; }
.mp-cta {
  /* Same Tron-style cta as the green Start Match button. */
  padding: 10px 28px;
  background: #000;
  border: 1px solid rgba(46,204,113,0.85);
  color: #8ef2ad;
  font-family: 'Rajdhani', sans-serif;
  font-size: 13px; font-weight: 700;
  letter-spacing: 3px; text-transform: uppercase;
  border-radius: 3px; cursor: pointer;
  box-shadow: 0 0 10px rgba(46,204,113,0.40);
  transition: all 0.15s;
}
.mp-cta:hover {
  border-color: rgba(46,204,113,1);
  box-shadow: 0 0 18px rgba(46,204,113,0.65);
  color: #b4f5c4;
}
.mp-leave {
  padding: 8px 18px;
  background: #000;
  border: 1px solid rgba(231,76,60,0.55);
  color: #f1948a;
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  border-radius: 3px; cursor: pointer;
  transition: all 0.15s;
}
.mp-leave:hover {
  border-color: rgba(231,76,60,1);
  box-shadow: 0 0 10px rgba(231,76,60,0.45);
  color: #ffb5ad;
}
.mp-hint {
  font-size: 11px; line-height: 1.5;
  color: #7a8a98;
  text-align: center;
  letter-spacing: 0.5px;
}
.mp-code-input {
  width: 220px;
  padding: 16px 20px;
  background: rgba(0,0,0,0.85);
  border: 1px solid var(--theme-accent-ring, rgba(79,195,247,0.55));
  border-radius: 3px;
  color: #f5fbff;
  font-family: 'Rajdhani', sans-serif;
  font-size: 30px; font-weight: 800;
  letter-spacing: 8px; text-transform: uppercase;
  text-align: center;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.mp-code-input:focus {
  border-color: var(--theme-accent-bright, #4fc3f7);
  box-shadow: 0 0 14px var(--theme-glow-outer, rgba(79,195,247,0.45));
}
.mp-status-label {
  font-size: 13px; font-weight: 700;
  letter-spacing: 4px; text-transform: uppercase;
  color: color-mix(in srgb, var(--theme-accent, rgb(79,195,247)) 30%, #9ecfed);
}
.mp-status-go { color: #8ef2ad; text-shadow: 0 0 8px rgba(46,204,113,0.65); }
.mp-status-warn { color: #ff8a7a; text-shadow: 0 0 8px rgba(231,76,60,0.55); }
.mp-pairing-line {
  font-size: 14px; color: #f5fbff; text-align: center;
}
.mp-code-display {
  font-family: 'Rajdhani', sans-serif;
  font-size: 56px; font-weight: 800;
  letter-spacing: 14px; text-transform: uppercase;
  color: #f5fbff;
  text-shadow:
    0 0 14px var(--theme-accent-bright, rgba(79,195,247,0.85)),
    0 0 32px var(--theme-glow-outer, rgba(79,195,247,0.45));
  padding: 14px 28px;
  background: rgba(0,0,0,0.85);
  border: 1px solid var(--theme-accent-ring, rgba(79,195,247,0.65));
  border-radius: 4px;
  cursor: pointer;
  user-select: all;
  transition: border-color 0.15s, transform 0.15s;
}
.mp-code-display:hover { border-color: var(--theme-accent-bright, #4fc3f7); }
.mp-code-display.mp-code-copied {
  transform: scale(1.04);
  border-color: rgba(46,204,113,0.85);
  box-shadow: 0 0 14px rgba(46,204,113,0.45);
}
/* Three-dot loader — drawn purely with CSS keyframes for "waiting"
   and "joining" states. Stays within the panel's neon language. */
.mp-loader {
  display: flex; gap: 10px; justify-content: center;
}
.mp-loader span {
  width: 10px; height: 10px;
  background: var(--theme-accent-bright, #4fc3f7);
  border-radius: 50%;
  box-shadow: 0 0 10px var(--theme-glow-outer, rgba(79,195,247,0.65));
  animation: mp-loader-bounce 1s infinite ease-in-out;
}
.mp-loader span:nth-child(2) { animation-delay: 0.15s; }
.mp-loader span:nth-child(3) { animation-delay: 0.30s; }
@keyframes mp-loader-bounce {
  0%, 80%, 100% { transform: scale(0.6); opacity: 0.4; }
  40%           { transform: scale(1.0); opacity: 1.0; }
}
.mp-transport-line {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--theme-accent-edge, rgba(79,195,247,0.18));
  font-size: 10px; line-height: 1.5;
  letter-spacing: 1px; text-transform: uppercase;
  text-align: center;
  color: #6a7a88;
}
.mp-transport-line code {
  background: rgba(0,0,0,0.65);
  border: 1px solid var(--theme-accent-edge, rgba(79,195,247,0.18));
  padding: 1px 6px;
  border-radius: 2px;
  color: color-mix(in srgb, var(--theme-accent, rgb(79,195,247)) 30%, #c4d6e0);
  font-family: 'Rajdhani', monospace;
  text-transform: none;
  letter-spacing: 0;
  font-size: 10px;
}
.mp-transport-line a {
  color: var(--theme-accent-bright, #4fc3f7);
  text-decoration: none;
  border-bottom: 1px dashed var(--theme-accent-bright, rgba(79,195,247,0.50));
}
.mp-transport-line a:hover {
  color: #f5fbff;
  border-bottom-color: #f5fbff;
}
@container (max-width: 520px) {
  .mp-panel { padding: 40px 20px 24px; }
  .mp-code-display { font-size: 42px; letter-spacing: 10px; padding: 12px 18px; }
  .mp-code-input { font-size: 26px; letter-spacing: 6px; }
}

.db-save-btn, .db-load-btn, .db-delete-btn, .db-start-btn,
.db-share-btn, .db-import-btn {
  background: #000;
  border: 1px solid rgba(var(--theme-rgb, 79,195,247), 0.70);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 40%, white);
  padding: 8px 16px;
  font-family: inherit;
  font-size: 11px; font-weight: 700;
  letter-spacing: 2px; text-transform: uppercase;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
}
.db-save-btn:hover, .db-load-btn:hover {
  border-color: rgba(var(--theme-rgb, 79,195,247), 1);
  box-shadow: 0 0 10px rgba(var(--theme-rgb, 79,195,247), 0.45);
  color: color-mix(in srgb, rgb(var(--theme-rgb, 79,195,247)) 25%, white);
}
.db-delete-btn { border-color: rgba(231,76,60,0.55); color: #f1948a; }
.db-delete-btn:hover { border-color: rgba(231,76,60,1); box-shadow: 0 0 10px rgba(231,76,60,0.45); color: #ffb5ad; }
.db-start-btn {
  padding: 10px 28px;
  border-color: rgba(46,204,113,0.85);
  color: #8ef2ad;
  font-size: 13px;
  box-shadow: 0 0 10px rgba(46,204,113,0.40);
}
.db-start-btn:hover {
  border-color: rgba(46,204,113,1);
  box-shadow: 0 0 18px rgba(46,204,113,0.65), inset 0 0 0 1px rgba(46,204,113,0.20);
  color: #b4f5c4;
}
.db-start-btn-disabled {
  opacity: 0.35;
  cursor: not-allowed;
  border-color: rgba(150,160,170,0.45);
  color: #8690a0;
  box-shadow: none;
}
.db-start-btn-disabled:hover {
  border-color: rgba(150,160,170,0.45);
  box-shadow: none;
  color: #8690a0;
}

/* ---- DRAFT OVERLAY — pure black to match the board ---- */
.draft-overlay {
  position: fixed; top: 0; left: 0; right: 0; bottom: 0;
  display: flex; align-items: center; justify-content: center;
  z-index: 200;
  background: #000000;
}
.draft-overlay > * { position: relative; z-index: 1; }

/* ============================================================
   DRAFT HUD — Tron chrome matching the game board
   - Outer panel has top/bottom hairlines with neon glow (same
     pattern as .board-section) + corner brackets so the whole
     screen reads as a single control surface.
   - Header row is a 3-column HUD: label · progress pips · counter.
   ============================================================ */
.draft-panel {
  text-align: center;
  max-width: 980px;
  width: 100%;
  padding: 28px 36px 32px;
  position: relative;
  background:
    radial-gradient(ellipse at top, rgba(255,255,255,0.04) 0%, rgba(255,255,255,0) 60%),
    #000000;
  border-top: 1px solid rgba(255,255,255,0.95);
  border-bottom: 1px solid rgba(255,255,255,0.95);
  box-shadow:
    0 -12px 14px -12px rgba(255,255,255,0.55),
    0  12px 14px -12px rgba(255,255,255,0.55);
}
.draft-panel.draft-tricks {
  /* Trick drafts share the same white chrome — keeps the UI consistent */
}

.draft-hud { margin-bottom: 26px; }
.draft-hud-row {
  display: flex; align-items: center; justify-content: space-between;
  gap: 18px; padding: 8px 4px 10px;
  border-bottom: 1px solid rgba(255,255,255,0.22);
}
.draft-hud-label {
  color: #ffffff;
  font-family: 'Rajdhani', sans-serif;
  font-size: 22px; font-weight: 800;
  letter-spacing: 6px; text-transform: uppercase;
  text-shadow:
    0 0 8px rgba(255,255,255,0.95),
    0 0 18px rgba(255,255,255,0.55),
    0 0 28px rgba(79,195,247,0.35);
  flex: 0 0 auto;
}
.draft-panel.draft-tricks .draft-hud-label {
  text-shadow:
    0 0 8px rgba(255,255,255,0.95),
    0 0 18px rgba(255,255,255,0.55),
    0 0 28px rgba(155,89,182,0.40);
}
.draft-hud-pips {
  display: inline-flex; align-items: center; gap: 8px;
  flex: 1 1 auto; justify-content: center;
}
.draft-pip {
  width: 9px; height: 9px; border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.55);
  background: transparent;
  box-shadow: inset 0 0 4px rgba(255,255,255,0.15);
  transition: transform 0.2s, box-shadow 0.2s;
}
.draft-pip.pip-done {
  background: #ffffff;
  border-color: #ffffff;
  box-shadow: 0 0 8px rgba(255,255,255,0.75), 0 0 14px rgba(255,255,255,0.35);
}
.draft-pip.pip-current {
  background: #ffffff;
  border-color: #ffffff;
  box-shadow: 0 0 10px rgba(255,255,255,0.95), 0 0 22px rgba(255,255,255,0.55);
  transform: scale(1.25);
  animation: draftPipPulse 1.4s ease-in-out infinite;
}
@keyframes draftPipPulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.55; }
}
.draft-hud-counter {
  flex: 0 0 auto;
  font-family: 'Rajdhani', sans-serif;
  color: #ffffff;
  font-size: 12px; font-weight: 700;
  letter-spacing: 2.8px; text-transform: uppercase;
  padding: 6px 14px; border-radius: 4px;
  background: rgba(12,12,12,0.55);
  border: 1px solid rgba(255,255,255,0.45);
  box-shadow:
    inset 0 0 8px rgba(255,255,255,0.08),
    0 0 8px rgba(255,255,255,0.20);
  text-shadow: 0 0 6px rgba(255,255,255,0.55);
}
.draft-hud-counter em {
  font-style: normal; color: #ffffff; font-weight: 800; font-size: 15px;
  margin: 0 2px;
  text-shadow: 0 0 10px rgba(255,255,255,0.95), 0 0 18px rgba(255,255,255,0.45);
}

.draft-hud-sub {
  color: #ffffff; margin-top: 12px;
  font-family: 'Rajdhani', sans-serif;
  font-size: 10px; letter-spacing: 3px; text-transform: uppercase;
  text-align: center;
  text-shadow:
    0 0 6px rgba(255,255,255,0.85),
    0 0 14px rgba(255,255,255,0.45),
    0 0 22px rgba(79,195,247,0.30);
}

/* Draft HUD actions row — Mulligan + Settings buttons side by side. */
.draft-hud-actions {
  display: inline-flex; align-items: center; gap: 14px;
  margin: 16px auto 0;
  flex-wrap: wrap; justify-content: center;
}
/* Mulligan — one-shot redraw button. Glows neon-white while available,
   dims and stops glowing after use. */
.draft-mulligan-btn {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 8px 20px;
  background: rgba(12,12,12,0.55);
  border: 1px solid rgba(255,255,255,0.65);
  border-radius: 4px;
  color: #ffffff;
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px; font-weight: 800;
  letter-spacing: 3.5px; text-transform: uppercase;
  cursor: pointer;
  text-shadow:
    0 0 6px rgba(255,255,255,0.85),
    0 0 14px rgba(255,255,255,0.45);
  box-shadow:
    0 0 10px rgba(255,255,255,0.45),
    0 0 22px rgba(255,255,255,0.20),
    inset 0 0 8px rgba(255,255,255,0.08);
  transition: transform 0.15s, box-shadow 0.25s, background 0.25s;
  animation: draftMulliganPulse 2s ease-in-out infinite;
}
/* Settings button on the draft screen — white chrome to match the Mulligan
   button's neutral styling (both are meta actions; cyan was reading as a
   primary-action color and competed with the draft choices). */
.draft-settings-btn,
.draft-quit-btn,
.draft-undo-btn {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 8px 20px;
  background: rgba(12,12,12,0.55);
  border: 1px solid rgba(255,255,255,0.65);
  border-radius: 4px;
  color: #ffffff;
  font-family: 'Rajdhani', sans-serif;
  font-size: 11px; font-weight: 800;
  letter-spacing: 3.5px; text-transform: uppercase;
  cursor: pointer;
  text-shadow:
    0 0 6px rgba(255,255,255,0.85),
    0 0 14px rgba(255,255,255,0.45);
  box-shadow:
    0 0 10px rgba(255,255,255,0.45),
    0 0 22px rgba(255,255,255,0.20),
    inset 0 0 8px rgba(255,255,255,0.08);
  transition: transform 0.15s, box-shadow 0.25s, background 0.25s;
}
/* Quit-to-menu is a softer tint (red border) so the eye knows it's a
   destructive-ish action without overpowering the primary draft choices. */
.draft-quit-btn {
  border-color: rgba(231,76,60,0.65);
  color: #ffb5ad;
  text-shadow: 0 0 6px rgba(231,76,60,0.70), 0 0 14px rgba(231,76,60,0.35);
  box-shadow:
    0 0 10px rgba(231,76,60,0.35),
    0 0 22px rgba(231,76,60,0.15),
    inset 0 0 8px rgba(231,76,60,0.06);
}
.draft-quit-btn:hover {
  transform: translateY(-1px);
  background: rgba(231,76,60,0.08);
  box-shadow:
    0 0 14px rgba(231,76,60,0.65),
    0 0 28px rgba(231,76,60,0.30),
    inset 0 0 10px rgba(231,76,60,0.12);
}
.draft-settings-btn:hover {
  transform: translateY(-1px);
  background: rgba(255,255,255,0.08);
  box-shadow:
    0 0 14px rgba(255,255,255,0.75),
    0 0 28px rgba(255,255,255,0.35),
    inset 0 0 10px rgba(255,255,255,0.12);
}
.draft-settings-btn:hover .mulligan-icon {
  transform: rotate(60deg);
}
.draft-mulligan-btn:hover {
  transform: translateY(-1px);
  background: rgba(255,255,255,0.08);
  box-shadow:
    0 0 14px rgba(255,255,255,0.75),
    0 0 28px rgba(255,255,255,0.35),
    inset 0 0 10px rgba(255,255,255,0.12);
}
.draft-mulligan-btn .mulligan-icon {
  display: inline-block;
  font-size: 15px; line-height: 1;
  transition: transform 0.3s;
}
.draft-mulligan-btn:hover .mulligan-icon {
  transform: rotate(-90deg);
}
.draft-mulligan-btn.mulligan-used,
.draft-mulligan-btn[disabled] {
  color: #5a6270;
  border-color: rgba(255,255,255,0.18);
  background: rgba(20,20,20,0.35);
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
  animation: none;
}
.draft-mulligan-btn.mulligan-used .mulligan-icon,
.draft-mulligan-btn[disabled] .mulligan-icon {
  opacity: 0.45;
}
.draft-mulligan-btn.mulligan-used:hover,
.draft-mulligan-btn[disabled]:hover {
  transform: none; background: rgba(20,20,20,0.35);
  box-shadow: none;
}
/* Undo / Back button — same skeleton as Settings/Quit (inherits from the
   grouped rule above), but with a left-arrow rotation on hover and a
   dimmed disabled state when no snapshot is on the stack (round 1 of a
   phase). Disabled state matches the mulligan-used dim so the two
   "unavailable" meta-actions read consistently. */
.draft-undo-btn:hover {
  transform: translateY(-1px);
  background: rgba(255,255,255,0.08);
  box-shadow:
    0 0 14px rgba(255,255,255,0.75),
    0 0 28px rgba(255,255,255,0.35),
    inset 0 0 10px rgba(255,255,255,0.12);
}
.draft-undo-btn:hover .mulligan-icon {
  transform: translateX(-2px) rotate(-10deg);
}
.draft-undo-btn.undo-disabled,
.draft-undo-btn[disabled] {
  color: #5a6270;
  border-color: rgba(255,255,255,0.18);
  background: rgba(20,20,20,0.35);
  text-shadow: none;
  box-shadow: none;
  cursor: not-allowed;
}
.draft-undo-btn.undo-disabled .mulligan-icon,
.draft-undo-btn[disabled] .mulligan-icon {
  opacity: 0.45;
}
.draft-undo-btn.undo-disabled:hover,
.draft-undo-btn[disabled]:hover {
  transform: none; background: rgba(20,20,20,0.35);
  box-shadow: none;
}
.draft-undo-btn.undo-disabled:hover .mulligan-icon,
.draft-undo-btn[disabled]:hover .mulligan-icon {
  transform: none;
}
@keyframes draftMulliganPulse {
  0%, 100% {
    box-shadow:
      0 0 10px rgba(255,255,255,0.45),
      0 0 22px rgba(255,255,255,0.20),
      inset 0 0 8px rgba(255,255,255,0.08);
  }
  50% {
    box-shadow:
      0 0 14px rgba(255,255,255,0.65),
      0 0 30px rgba(255,255,255,0.30),
      inset 0 0 10px rgba(255,255,255,0.12);
  }
}
.draft-panel.draft-tricks .draft-hud-sub {
  text-shadow:
    0 0 6px rgba(255,255,255,0.85),
    0 0 14px rgba(255,255,255,0.45),
    0 0 22px rgba(155,89,182,0.35);
}
.draft-choices { display: flex; gap: 48px; justify-content: center; margin-bottom: 24px; flex-wrap: wrap; }

/* ---- Multiplayer draft "waiting for opponent" placeholder ----
   Shown when this client has picked but the other hasn't.
   `playerChoices` is cleared after a partial pick (see game.js
   draftPick) and this card slides in in their place. Keeps the
   draft layout reserving the same vertical real-estate so the
   chrome above (pip strip, mulligan, etc.) doesn't jump. */
.draft-waiting {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  min-height: 320px;
  min-width: 240px;
  padding: 32px 28px;
  border: 1px dashed rgba(var(--theme-rgb, 79, 195, 247), 0.45);
  border-radius: 8px;
  background:
    radial-gradient(ellipse at 50% 30%,
      rgba(var(--theme-rgb, 79, 195, 247), 0.06) 0%,
      transparent 70%),
    #060a12;
  color: rgba(255, 255, 255, 0.82);
  box-shadow: 0 0 18px rgba(var(--theme-rgb, 79, 195, 247), 0.15);
}
.draft-waiting-spinner {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 2px solid rgba(var(--theme-rgb, 79, 195, 247), 0.18);
  border-top-color: rgba(var(--theme-rgb, 79, 195, 247), 0.95);
  animation: draftWaitingSpin 1.1s linear infinite;
}
@keyframes draftWaitingSpin {
  to { transform: rotate(360deg); }
}
.draft-waiting-title {
  font-family: 'Rajdhani', sans-serif;
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: rgba(var(--theme-rgb, 79, 195, 247), 0.95);
  text-shadow: 0 0 8px rgba(var(--theme-rgb, 79, 195, 247), 0.45);
}
.draft-waiting-sub {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.55);
  letter-spacing: 0.3px;
}
@media (prefers-reduced-motion: reduce) {
  .draft-waiting-spinner { animation: none; }
}

/* ---- Draft card — Tron: black core, rarity tint via border ---- */
/* Rarity scale:
     cost 0-3  → green  (common)
     cost 4-6  → cyan   (uncommon)
     cost 7-8  → glowing silver (rare)
     cost 9-10 → glowing gold   (legendary) */
/* Draft cards — glow intensities harmonized with on-board ally / enemy
   card spec: 12px @ 45% alpha + 24px @ 18% alpha (matches the "glow
   stack" used across the whole board so rarity reads continuously from
   draft → hand → board without the draft looking dimmer). The 6px
   vertical drop-shadow layer is kept for depth against the dark draft
   overlay background. */
/* Draft-card chrome.
   Sizing follows user direction in two passes:
     pass 1: "the smaller spacing is right" — unify at hand-card 140 px
     pass 2: "still too small... I want them to be like playing cards.
             take up the screen, but keep the consistency in where all
             the elements are in the small version"
   Final: 220 px wide draft cards (≈1.57× the 140 px hand card) with the
   chrome (cost, orbs, name overlay, desc, bold labels) scaled by the
   same factor so badges, stats, and text retain the same in-card
   PROPORTIONS as the small in-hand version — just rendered at picker
   scale so 4-badge cards like Galactus stop spilling over the right
   edge. The .card.draft-card selector (specificity 0,2,0) beats both
   .card (140 px) and the bare .draft-card rule (no width), which is
   why we anchor on the chained class for the override. */
.draft-card {
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
  position: relative;
  color: #e6eef5;
}
.card.draft-card {
  width: 220px !important;
  min-height: 320px;
  padding: 8px 8px 10px;
}
.card.draft-card .card-cost {
  width: 32px; height: 32px;
  font-size: 16px;
  top: 9px; left: 9px;
}
.card.draft-card .stat-circle {
  width: 32px; height: 32px;
  font-size: 15px;
  bottom: 8px;
}
.card.draft-card .stat-atk { left: 8px; }
.card.draft-card .stat-hp  { right: 8px; }
.card.draft-card .card-name-overlay {
  font-size: 14px;
  letter-spacing: 0.10em;
  padding: 14px 8px 6px;
}
.card.draft-card .card-desc {
  font-size: 11px;
  letter-spacing: 0.20px;
  padding-bottom: 38px;
}
.card.draft-card .card-desc b {
  font-size: 10px;
  letter-spacing: 0.65px;
}
.card.draft-card .status-badge {
  font-size: 10px;
  padding: 2px 6px;
  letter-spacing: 0.45px;
}
/* Trick-draft cards lost their width when .draft-card's blanket 220 px
   override was removed — the bare .draft-card selector now sets no
   width and .trick-draft doesn't carry the `card` class, so without
   this restore the trick picker stretched to fill the viewport. Match
   the card draft's 220 px so both pickers feel like one screen. */
.draft-card.trick-draft {
  width: 220px;
  min-height: 200px;
  padding: 14px 14px 18px;
}
.draft-card,
.draft-card.cost-0, .draft-card.cost-1, .draft-card.cost-2, .draft-card.cost-3 {
  background: #060a12 !important;
  border: 1px solid rgba(46,204,113,0.95) !important;
  box-shadow:
    0 0 12px rgba(46,204,113,0.45),
    0 0 24px rgba(46,204,113,0.18),
    0 6px 18px rgba(0,0,0,0.55),
    inset 0 0 0 1px rgba(46,204,113,0.10) !important;
}
.draft-card.cost-4, .draft-card.cost-5, .draft-card.cost-6 {
  border-color: rgba(79,195,247,0.95) !important;
  background: #060a12 !important;
  box-shadow:
    0 0 12px rgba(79,195,247,0.45),
    0 0 24px rgba(79,195,247,0.18),
    0 6px 18px rgba(0,0,0,0.55),
    inset 0 0 0 1px rgba(79,195,247,0.10) !important;
}
.draft-card.cost-7, .draft-card.cost-8 {
  border-color: rgba(240,245,250,0.95) !important;
  background: #060a12 !important;
  box-shadow:
    0 0 12px rgba(240,245,250,0.45),
    0 0 24px rgba(240,245,250,0.18),
    0 6px 18px rgba(0,0,0,0.55),
    inset 0 0 0 1px rgba(240,245,250,0.10) !important;
}
.draft-card.cost-9, .draft-card.cost-10 {
  border-color: rgba(255,215,0,0.95) !important;
  background: #060a12 !important;
  box-shadow:
    0 0 12px rgba(255,215,0,0.45),
    0 0 24px rgba(255,215,0,0.18),
    0 6px 18px rgba(0,0,0,0.55),
    inset 0 0 0 1px rgba(255,215,0,0.12) !important;
}
/* Inner hairline — Tron double-edge */
.draft-card::before {
  content: ''; position: absolute; inset: 4px;
  border-radius: 3px;
  border: 1px solid rgba(79,195,247,0.12);
  pointer-events: none;
}
/* Corner brackets */
.draft-card::after {
  content: ''; position: absolute; inset: 0;
  pointer-events: none; border-radius: 6px;
  background:
    linear-gradient(var(--tron-edge), var(--tron-edge)) top    left   / 12px 1px no-repeat,
    linear-gradient(var(--tron-edge), var(--tron-edge)) top    left   / 1px 12px no-repeat,
    linear-gradient(var(--tron-edge), var(--tron-edge)) top    right  / 12px 1px no-repeat,
    linear-gradient(var(--tron-edge), var(--tron-edge)) top    right  / 1px 12px no-repeat,
    linear-gradient(var(--tron-edge), var(--tron-edge)) bottom left   / 12px 1px no-repeat,
    linear-gradient(var(--tron-edge), var(--tron-edge)) bottom left   / 1px 12px no-repeat,
    linear-gradient(var(--tron-edge), var(--tron-edge)) bottom right  / 12px 1px no-repeat,
    linear-gradient(var(--tron-edge), var(--tron-edge)) bottom right  / 1px 12px no-repeat;
  opacity: 0.8;
}
/* Default hover — green (common). Each rarity tier overrides below. */
.draft-card:hover {
  transform: translateY(-8px);
  border-color: rgba(46,204,113,1) !important;
  box-shadow:
    0 0 22px rgba(46,204,113,0.75),
    0 14px 32px rgba(46,204,113,0.25),
    inset 0 0 0 1px rgba(46,204,113,0.15) !important;
}
/* Uncommon (cost 4-6) — cyan hover */
.draft-card.cost-4:hover,
.draft-card.cost-5:hover,
.draft-card.cost-6:hover {
  border-color: rgba(79,195,247,1) !important;
  box-shadow:
    0 0 22px rgba(79,195,247,0.75),
    0 14px 32px rgba(79,195,247,0.25),
    inset 0 0 0 1px rgba(79,195,247,0.15) !important;
}
/* Rare (cost 7-8) — silver hover */
.draft-card.cost-7:hover,
.draft-card.cost-8:hover {
  border-color: rgba(230,240,250,1) !important;
  box-shadow:
    0 0 26px rgba(240,245,250,0.85),
    0 0 44px rgba(240,245,250,0.40),
    0 14px 32px rgba(0,0,0,0.55),
    inset 0 0 0 1px rgba(240,245,250,0.20) !important;
}
/* Legendary (cost 9-10) — gold hover */
.draft-card.cost-9:hover,
.draft-card.cost-10:hover {
  border-color: rgba(255,215,0,1) !important;
  box-shadow:
    0 0 26px rgba(255,215,0,0.90),
    0 0 48px rgba(255,215,0,0.45),
    0 14px 32px rgba(0,0,0,0.55),
    inset 0 0 0 1px rgba(255,215,0,0.22) !important;
}

/* Draft-card cost + orbs now inherit from the unified `.card-cost`
   and `.stat-atk` / `.stat-hp` base rules — same chamfered octagon
   mask + neon outline + drop-shadow as the in-hand and on-board
   chrome. No separate draft-only treatment: the picker reads as
   "this is the same card you'll see in your hand." */

/* Draft-card tier edge variable — used by the name banner's underscan hairline
   and diamond node. Keeps the rarity signal consistent with hand/board cards. */
.draft-card.cost-0, .draft-card.cost-1,
.draft-card.cost-2, .draft-card.cost-3 { --card-edge: rgba(46,204,113,0.85); }
.draft-card.cost-4, .draft-card.cost-5, .draft-card.cost-6 { --card-edge: rgba(79,195,247,0.80); }
.draft-card.cost-7, .draft-card.cost-8 { --card-edge: rgba(240,245,250,0.90); }
.draft-card.cost-9, .draft-card.cost-10 { --card-edge: rgba(255,215,0,0.95); }

/* Name banner — single underscan + centered diamond node, same language as
   hand/board cards. Larger diamond to match the draft card's larger scale. */
.draft-card .card-name-banner {
  margin: 4px 0 14px;
  padding: 7px 8px 8px;
  border-bottom: 1px solid var(--card-edge);
  position: relative;
}
.draft-card .card-name-banner::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 50%;
  width: 7px; height: 7px;
  transform: translateX(-50%) rotate(45deg);
  background: var(--card-edge);
  box-shadow: 0 0 5px var(--card-edge), 0 0 10px var(--card-edge);
  z-index: 3;
}
.draft-card .card-name {
  font-family: 'Rajdhani', 'Segoe UI', system-ui, sans-serif;
  font-size: 18px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 2.2px;
  color: #f5fbff;
  text-shadow: 0 0 8px rgba(79,195,247,0.50), 0 1px 3px rgba(0,0,0,0.95);
}
/* Rarity-tiered name color per tier — matches hand-card rarity language. */
.draft-card.cost-0 .card-name, .draft-card.cost-1 .card-name,
.draft-card.cost-2 .card-name, .draft-card.cost-3 .card-name {
  color: #8ef2ad;
  text-shadow:
    0 0 4px rgba(46,204,113,1),
    0 0 12px rgba(46,204,113,0.65),
    0 0 20px rgba(46,204,113,0.35),
    0 1px 2px rgba(0,0,0,0.95);
}
.draft-card.cost-4 .card-name, .draft-card.cost-5 .card-name, .draft-card.cost-6 .card-name {
  color: #9adcff;
  text-shadow:
    0 0 4px rgba(79,195,247,1),
    0 0 12px rgba(79,195,247,0.65),
    0 0 20px rgba(79,195,247,0.35),
    0 1px 2px rgba(0,0,0,0.95);
}
.draft-card.cost-7 .card-name, .draft-card.cost-8 .card-name {
  color: #f4f8fd;
  text-shadow:
    0 0 4px rgba(240,245,250,1),
    0 0 12px rgba(240,245,250,0.85),
    0 0 20px rgba(240,245,250,0.50),
    0 1px 2px rgba(0,0,0,0.95);
}
.draft-card.cost-9 .card-name, .draft-card.cost-10 .card-name {
  color: #ffe066;
  text-shadow:
    0 0 4px rgba(255,215,0,1),
    0 0 12px rgba(255,215,0,0.75),
    0 0 20px rgba(255,215,0,0.45),
    0 1px 2px rgba(0,0,0,0.95);
}

.draft-card .card-abilities {
  font-family: 'Rajdhani', 'Segoe UI', system-ui, sans-serif;
  font-size: 12px; color: #d5dfe8; margin-bottom: 10px;
  font-style: normal; letter-spacing: 1.2px; font-weight: 600;
  text-transform: uppercase;
  min-height: 0;
}
/* Draft-card body text + stat orbs intentionally inherit the
   unified `.card-desc` + `.stat-circle` rules (monospace + rarity-
   tinted base, chamfered octagon orbs). The previous draft-only
   Rajdhani-white desc and oversized -12px corner orbs were removed
   so the picker chrome matches the hand and board exactly. */

/* ---- Trick draft — purple neon edge (no rarity — all tricks look equal) ---- */
.draft-card.trick-draft {
  background:
    linear-gradient(180deg, rgba(155,89,182,0.06) 0%, rgba(155,89,182,0) 45%),
    #060a12 !important;
  border: 1px solid rgba(155,89,182,0.70) !important;
  border-radius: 6px;
  min-height: 200px;
  box-shadow:
    0 0 10px rgba(155,89,182,0.30),
    0 6px 18px rgba(0,0,0,0.55),
    inset 0 0 0 1px rgba(155,89,182,0.06) !important;
}
.draft-card.trick-draft::before {
  content: ''; position: absolute; inset: 4px;
  border-radius: 3px;
  border: 1px solid rgba(155,89,182,0.14);
  background: none;
  pointer-events: none;
}
.draft-card.trick-draft::after {
  content: ''; position: absolute; inset: 0; border-radius: 6px;
  pointer-events: none;
  background:
    linear-gradient(rgba(155,89,182,0.65), rgba(155,89,182,0.65)) top    left   / 12px 1px no-repeat,
    linear-gradient(rgba(155,89,182,0.65), rgba(155,89,182,0.65)) top    left   / 1px 12px no-repeat,
    linear-gradient(rgba(155,89,182,0.65), rgba(155,89,182,0.65)) top    right  / 12px 1px no-repeat,
    linear-gradient(rgba(155,89,182,0.65), rgba(155,89,182,0.65)) top    right  / 1px 12px no-repeat,
    linear-gradient(rgba(155,89,182,0.65), rgba(155,89,182,0.65)) bottom left   / 12px 1px no-repeat,
    linear-gradient(rgba(155,89,182,0.65), rgba(155,89,182,0.65)) bottom left   / 1px 12px no-repeat,
    linear-gradient(rgba(155,89,182,0.65), rgba(155,89,182,0.65)) bottom right  / 12px 1px no-repeat,
    linear-gradient(rgba(155,89,182,0.65), rgba(155,89,182,0.65)) bottom right  / 1px 12px no-repeat;
}
.draft-card.trick-draft:hover {
  transform: translateY(-8px);
  border-color: #9b59b6 !important;
  box-shadow:
    0 0 18px rgba(155,89,182,0.55),
    0 14px 32px rgba(125,60,152,0.30),
    inset 0 0 0 1px rgba(155,89,182,0.12) !important;
}
.draft-card .trick-cost {
  position: absolute; top: -10px; left: -10px;
  width: 30px; height: 30px; border-radius: 50%;
  background: #000000;
  color: #d7b3e6; font-weight: 900; font-size: 15px;
  display: flex; align-items: center; justify-content: center;
  /* Match the HUD tricks divider / count — fully saturated amethyst. */
  border: 1px solid rgba(155,89,182,1);
  box-shadow: 0 0 12px rgba(155,89,182,0.80), 0 0 24px rgba(155,89,182,0.40);
  text-shadow: 0 0 6px rgba(155,89,182,0.95), 0 0 12px rgba(155,89,182,0.45);
  z-index: 3;
}
/* Type sigils for cards on the draft screen — mirror the in-game placement
   (top-right corner, overlapping the card border) and take the card's rarity
   color (blue common / green uncommon / silver rare / gold legendary). */
.draft-card .card-type-sigil {
  position: absolute; top: -6px; right: -4px;
  font-size: 16px;
  pointer-events: none;
  line-height: 1;
  z-index: 4;
}
/* Cost 0-3 — blue common (default) */
.draft-card.cost-0 .card-type-sigil,
.draft-card.cost-1 .card-type-sigil,
.draft-card.cost-2 .card-type-sigil,
.draft-card.cost-3 .card-type-sigil {
  color: #7fd0ff;
  text-shadow: 0 0 8px rgba(79,195,247,0.85);
}
/* Cost 4-6 — green uncommon */
.draft-card.cost-4 .card-type-sigil,
.draft-card.cost-5 .card-type-sigil,
.draft-card.cost-6 .card-type-sigil {
  color: #7ee8a5;
  text-shadow: 0 0 8px rgba(46,204,113,0.85);
}
/* Cost 7-8 — silver rare */
.draft-card.cost-7 .card-type-sigil,
.draft-card.cost-8 .card-type-sigil {
  color: #e8eef6;
  text-shadow: 0 0 10px rgba(240,245,250,0.9);
}
/* Cost 9-10 — gold legendary */
.draft-card.cost-9 .card-type-sigil,
.draft-card.cost-10 .card-type-sigil {
  color: #ffd77a;
  text-shadow: 0 0 10px rgba(255,215,0,0.95);
}
.draft-card .trick-name {
  /* Match .card-name-banner — single underscan hairline + centered diamond. */
  font-family: 'Rajdhani', 'Segoe UI', system-ui, sans-serif;
  font-size: 18px; font-weight: 700; color: #d7b3e6;
  margin: 14px 0 14px;
  text-transform: uppercase; letter-spacing: 2.2px;
  padding-bottom: 10px;
  background: transparent;
  border-bottom: 1px solid rgba(155,89,182,0.75);
  text-shadow: 0 0 10px rgba(155,89,182,0.60), 0 1px 3px rgba(0,0,0,0.85);
  position: relative;
}
.draft-card .trick-name::after {
  content: '';
  position: absolute;
  bottom: -4px;
