/* ============================================================
   PLAYER-SIDE THEMING — the selected neon colour drives the
   player's health bar, block meter, ally cards, and lane
   occupancy tint, so the "my side" chrome coordinates with the
   menu. Enemy stays red by default; if the player picks red as
   their theme we swap the enemy to blue so the two sides never
   overlap.

   Uses --player-* and --enemy-* RGB triplets declared on body;
   each body.theme-* variant sets both.
   ============================================================ */
body, :root {
  --player-r: 79;  --player-g: 195; --player-b: 247;   /* cyan default */
  --enemy-r:  231; --enemy-g:  76;  --enemy-b:  60;    /* red default */
  /* Hand-picked POP color for the contested-lane midpoint. The naive
     50/50 sRGB mix between AI red and the player accent produces
     muddy, low-saturation mids (cyan+red = washed mauve, white+red =
     dull salmon). User direction: "make the middle POP — like
     red+blue should be vibrant magenta, not muddy purple." So we
     hand-pick a saturated, vivid mid per theme that LOOKS like the
     color-wheel mix but stays neon-bright.
       cyan default + red → vivid magenta */
  --contest-pop: rgb(255, 60, 200);
  --contest-pop-soft: rgba(255, 60, 200, 0.55);
}
/* Per-theme contest-pop overrides — hand-tuned so the midpoint always
   reads as saturated neon, never muddy. */
body.theme-red, :root.theme-red {
  --player-r: 231; --player-g: 76;  --player-b: 60;
  --enemy-r:  79;  --enemy-g:  195; --enemy-b:  247;
  --contest-pop: rgb(255, 60, 200);
  --contest-pop-soft: rgba(255, 60, 200, 0.55);
}
body.theme-gold, :root.theme-gold {
  --player-r: 255; --player-g: 215; --player-b: 0;
  --contest-pop: rgb(255, 130, 20);            /* vivid orange (gold+red) */
  --contest-pop-soft: rgba(255, 130, 20, 0.55);
}
body.theme-green, :root.theme-green {
  --player-r: 46;  --player-g: 204; --player-b: 113;
  --contest-pop: rgb(255, 220, 30);            /* bright yellow (green+red) */
  --contest-pop-soft: rgba(255, 220, 30, 0.55);
}
body.theme-silver, :root.theme-silver {
  --player-r: 220; --player-g: 226; --player-b: 234;
  --contest-pop: rgb(255, 80, 170);            /* HOT PINK (white+red) */
  --contest-pop-soft: rgba(255, 80, 170, 0.55);
}
body.theme-purple, :root.theme-purple {
  --player-r: 155; --player-g: 89;  --player-b: 182;
  --contest-pop: rgb(230, 50, 150);            /* vivid magenta (purple+red) */
  --contest-pop-soft: rgba(230, 50, 150, 0.55);
}
body {
  --player-accent:       rgb(var(--player-r), var(--player-g), var(--player-b));
  --player-accent-edge:  rgba(var(--player-r), var(--player-g), var(--player-b), 0.55);
  --player-accent-bright:rgba(var(--player-r), var(--player-g), var(--player-b), 0.95);
  --player-glow-inner:   rgba(var(--player-r), var(--player-g), var(--player-b), 0.22);
  --player-glow-outer:   rgba(var(--player-r), var(--player-g), var(--player-b), 0.45);
  --player-wash-08:      rgba(var(--player-r), var(--player-g), var(--player-b), 0.08);
  --enemy-accent-edge:   rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.55);
  --enemy-accent-bright: rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.95);
  --enemy-glow-inner:    rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.22);
  --enemy-glow-outer:    rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.45);
  --enemy-wash-08:       rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.08);
}

/* Player banner — recolour the gradient wash, border + glow to player theme. */
.info-bar.player-bar {
  background:
    linear-gradient(0deg, var(--player-wash-08), transparent 50%),
    linear-gradient(180deg, #07080f, #0a0f18) !important;
  border-top-color: var(--player-accent-bright) !important;
  border-bottom-color: var(--player-accent-bright) !important;
  box-shadow:
    0 0 6px var(--player-glow-outer),
    0 0 12px var(--player-glow-inner),
    inset 0 1px 0 rgba(var(--player-r), var(--player-g), var(--player-b), 0.22),
    inset 0 -1px 0 rgba(var(--player-r), var(--player-g), var(--player-b), 0.22) !important;
}
.info-bar.ai-bar {
  background:
    linear-gradient(180deg, var(--enemy-wash-08), transparent 50%),
    linear-gradient(180deg, #0a0f18, #07080f) !important;
  border-top-color: var(--enemy-accent-bright) !important;
  border-bottom-color: var(--enemy-accent-bright) !important;
  box-shadow:
    0 0 6px var(--enemy-glow-outer),
    0 0 12px var(--enemy-glow-inner),
    inset 0 1px 0 rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.22),
    inset 0 -1px 0 rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.22) !important;
}
/* Player health bar + fill */
.player-bar .health-bar {
  border-color: var(--player-accent-bright) !important;
  box-shadow: 0 0 6px var(--player-glow-outer), 0 0 14px var(--player-glow-inner) !important;
}
.ai-bar .health-bar {
  border-color: var(--enemy-accent-bright) !important;
  box-shadow: 0 0 6px var(--enemy-glow-outer), 0 0 14px var(--enemy-glow-inner) !important;
}
.health-fill.player-hp {
  background: linear-gradient(90deg,
    rgba(var(--player-r), var(--player-g), var(--player-b), 0.08),
    rgba(var(--player-r), var(--player-g), var(--player-b), 0.20)) !important;
  box-shadow:
    inset -2px 0 0 0 rgba(var(--player-r), var(--player-g), var(--player-b), 1),
    2px 0 4px rgba(var(--player-r), var(--player-g), var(--player-b), 0.65),
    4px 0 10px rgba(var(--player-r), var(--player-g), var(--player-b), 0.30) !important;
}
.health-fill.ai-hp {
  background: linear-gradient(90deg,
    rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.08),
    rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.24)) !important;
  box-shadow:
    inset -2px 0 0 0 rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 1),
    2px 0 4px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.70),
    4px 0 10px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.32) !important;
}
.health-text.player-color {
  color: color-mix(in srgb, var(--player-accent) 35%, white) !important;
  text-shadow:
    0 0 3px var(--player-accent-bright),
    0 0 8px var(--player-glow-outer),
    0 1px 2px rgba(0,0,0,0.8) !important;
}
.health-text.ai-color {
  color: color-mix(in srgb, rgb(var(--enemy-r), var(--enemy-g), var(--enemy-b)) 35%, white) !important;
  text-shadow:
    0 0 3px var(--enemy-accent-bright),
    0 0 8px var(--enemy-glow-outer),
    0 1px 2px rgba(0,0,0,0.8) !important;
}
/* Block meter — player + AI sides follow their respective theme. */
.player-bar .block-circle {
  border-color: var(--player-accent-bright) !important;
  box-shadow: 0 0 7px var(--player-glow-outer), 0 0 14px var(--player-glow-inner) !important;
}
.ai-bar .block-circle {
  border-color: var(--enemy-accent-bright) !important;
  box-shadow: 0 0 7px var(--enemy-glow-outer), 0 0 14px var(--enemy-glow-inner) !important;
}
/* Player ally cards — frame + gradient wash uses player theme. */
.card.ally-card {
  --card-edge: var(--player-accent-bright);
  border-color: var(--player-accent-bright) !important;
  background-color: #060a12 !important;
  background-image: linear-gradient(180deg, var(--player-wash-08) 0%, rgba(0,0,0,0) 55%) !important;
  box-shadow:
    inset 0 0 0 1px rgba(var(--player-r), var(--player-g), var(--player-b), 0.14),
    0 0 8px rgba(var(--player-r), var(--player-g), var(--player-b), 0.28),
    0 0 18px rgba(var(--player-r), var(--player-g), var(--player-b), 0.10),
    0 4px 12px rgba(0,0,0,0.55) !important;
}
.card.ally-card:hover {
  border-color: var(--player-accent-bright) !important;
  box-shadow:
    inset 0 0 0 1px rgba(var(--player-r), var(--player-g), var(--player-b), 0.22),
    0 0 12px rgba(var(--player-r), var(--player-g), var(--player-b), 0.45),
    0 0 24px rgba(var(--player-r), var(--player-g), var(--player-b), 0.20),
    0 4px 10px rgba(0,0,0,0.5) !important;
}
.card.enemy-card {
  --card-edge: var(--enemy-accent-bright);
  border-color: var(--enemy-accent-bright) !important;
  background-color: #060a12 !important;
  background-image: linear-gradient(180deg, var(--enemy-wash-08) 0%, rgba(0,0,0,0) 55%) !important;
  box-shadow:
    inset 0 0 0 1px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.14),
    0 0 8px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.32),
    0 0 18px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.12),
    0 4px 12px rgba(0,0,0,0.55) !important;
}
.card.enemy-card:hover {
  border-color: var(--enemy-accent-bright) !important;
  box-shadow:
    inset 0 0 0 1px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.22),
    0 0 12px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.50),
    0 0 24px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.22),
    0 4px 10px rgba(0,0,0,0.5) !important;
}
/* Lane occupancy — colour the centerline + number pip by owner using
   the player/enemy theme vars. "Contested" (occ-both) stays gold as
   a neutral contested-state signal. */
.lane.occ-player .lane-sep::before {
  background: linear-gradient(90deg,
    transparent,
    rgba(var(--player-r), var(--player-g), var(--player-b), 0.95) 30%,
    rgba(var(--player-r), var(--player-g), var(--player-b), 0.95) 70%,
    transparent) !important;
  box-shadow:
    0 0 8px rgba(var(--player-r), var(--player-g), var(--player-b), 0.32),
    0 0 16px rgba(var(--player-r), var(--player-g), var(--player-b), 0.12) !important;
}
.lane.occ-player .lane-number {
  border-color: var(--player-accent-bright) !important;
  color: color-mix(in srgb, var(--player-accent) 35%, white) !important;
  box-shadow:
    0 0 8px rgba(var(--player-r), var(--player-g), var(--player-b), 0.32),
    0 0 16px rgba(var(--player-r), var(--player-g), var(--player-b), 0.12) !important;
}
.lane.occ-ai .lane-sep::before {
  background: linear-gradient(90deg,
    transparent,
    rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.95) 30%,
    rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.95) 70%,
    transparent) !important;
  box-shadow:
    0 0 8px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.32),
    0 0 16px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.12) !important;
}
.lane.occ-ai .lane-number {
  border-color: var(--enemy-accent-bright) !important;
  color: color-mix(in srgb, rgb(var(--enemy-r), var(--enemy-g), var(--enemy-b)) 35%, white) !important;
  box-shadow:
    0 0 8px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.32),
    0 0 16px rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.12) !important;
}
/* Contested centerline — uses the hand-picked --contest-pop mid color
   so the seam saturates instead of muddying. */
.lane.occ-both .lane-sep::before {
  background: linear-gradient(90deg,
    transparent,
    rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.70) 20%,
    var(--contest-pop, rgb(255, 60, 200)) 50%,
    rgba(var(--player-r), var(--player-g), var(--player-b), 0.70) 80%,
    transparent) !important;
}

/* ============================================================
   SETTINGS CONTROLS THEMED — dropdowns, checkboxes, Cancel.
   ============================================================ */
.settings-row select {
  background: #060a12 !important;
  color: #f0f6fb !important;
  border: 1px solid var(--theme-accent-edge) !important;
  border-radius: 4px;
  padding: 5px 10px !important;
  font-weight: 600;
}
.settings-row select option {
  background: #060a12;
  color: #f0f6fb;
}
/* Use accent-color on checkboxes — it's the only cross-browser hook
   that tints the native checkbox fill without replacing it. */
.settings-row input[type="checkbox"] {
  accent-color: var(--theme-accent) !important;
  width: 16px; height: 16px;
  cursor: pointer;
}
.settings-row label {
  color: color-mix(in srgb, var(--theme-accent) 30%, #cfd8e0) !important;
}
/* Secondary button (Cancel) — outline-only theme, so it's clearly
   less-emphasis than the filled primary (Save) but still themed. */
.btn-secondary {
  border-color: var(--theme-accent-edge) !important;
  color: color-mix(in srgb, var(--theme-accent) 40%, white) !important;
  box-shadow:
    0 0 6px var(--theme-glow-inner),
    0 0 12px rgba(0,0,0,0) !important;
  text-shadow: 0 0 5px var(--theme-glow-inner) !important;
}
.btn-secondary:hover {
  border-color: var(--theme-accent-bright) !important;
  color: #f5fbff !important;
  box-shadow: 0 0 10px var(--theme-glow-outer), 0 0 20px var(--theme-glow-inner) !important;
}
/* Settings panel h2 — pick up theme colour. */
.settings-panel h2,
.round-summary-panel h2 {
  color: color-mix(in srgb, var(--theme-accent) 40%, #f5fbff) !important;
  text-shadow: 0 0 8px var(--theme-glow-outer) !important;
}

/* ============================================================
   MODE SELECT + DRAFT LABELS + BACK BUTTONS THEMED
   ============================================================ */
/* "CHOOSE A MATCH MODE" subtitle */
.mode-subtitle {
  color: color-mix(in srgb, var(--theme-accent) 40%, #cfe9fb) !important;
  text-shadow: 0 0 6px var(--theme-glow-outer) !important;
}
/* Mode-row label ("1V1 VS AI", "2V2") */
.mode-row-label {
  color: color-mix(in srgb, var(--theme-accent) 45%, #e8f5ff) !important;
  text-shadow: 0 0 6px var(--theme-glow-inner) !important;
}
.mode-option-label {
  color: color-mix(in srgb, var(--theme-accent) 55%, white) !important;
  text-shadow: 0 0 8px var(--theme-glow-outer) !important;
}
.mode-option-sub {
  color: color-mix(in srgb, var(--theme-accent) 30%, #cfe9fb) !important;
}
/* Draft label + hud-label */
.draft-hud-label,
.draft-subtext,
.draft-hud-counter {
  color: color-mix(in srgb, var(--theme-accent) 35%, #ffffff) !important;
  text-shadow:
    0 0 8px var(--theme-glow-outer),
    0 0 18px var(--theme-glow-inner) !important;
}
/* Draft panel corner brackets picked up theme (already theme-aware
   via --theme-accent fallback), but draft-panel uses white by default.
   Override to theme for the card-draft variant only (trick draft keeps
   purple from rule above). */
.draft-panel:not(.draft-tricks)::before,
.draft-panel:not(.draft-tricks)::after {
  border-color: var(--theme-accent-bright) !important;
  filter: drop-shadow(0 0 6px var(--theme-glow-outer)) !important;
}
/* Menu back button in draft */
.draft-menu-btn,
.mode-back,
.md-back,
.stats-back,
.db-back {
  border-color: var(--theme-accent-edge) !important;
  color: color-mix(in srgb, var(--theme-accent) 50%, white) !important;
  background: #000 !important;
}
.draft-menu-btn:hover,
.mode-back:hover,
.md-back:hover,
.stats-back:hover,
.db-back:hover {
  border-color: var(--theme-accent-bright) !important;
  color: #f5fbff !important;
  box-shadow: 0 0 8px var(--theme-glow-outer), 0 0 16px var(--theme-glow-inner) !important;
}

/* ============================================================
   DECK BUILDER REVAMP — apply the main-menu polish (panel frame,
   corner brackets, themed title + borders). Existing grid/cards
   stay, just the chrome gets an upgrade.
   ============================================================ */
.deckbuilder-overlay { padding: 18px; }
.db-panel {
  position: relative;
  background:
    linear-gradient(180deg, var(--theme-wash-05) 0%, rgba(0,0,0,0) 40%),
    #000 !important;
  border: 1px solid var(--theme-accent-edge);
  border-radius: 4px;
  box-shadow:
    0 0 28px var(--theme-glow-outer),
    0 0 60px var(--theme-glow-inner),
    inset 0 0 0 1px var(--theme-wash-08),
    inset 0 1px 0 var(--theme-accent-edge);
}
.db-panel::before,
.db-panel::after {
  content: "";
  position: absolute;
  width: 18px; height: 18px;
  pointer-events: none;
  z-index: 5;
}
.db-panel::before {
  top: -1px; left: -1px;
  border-top: 2px solid var(--theme-accent);
  border-left: 2px solid var(--theme-accent);
  filter: drop-shadow(0 0 6px var(--theme-glow-outer));
}
.db-panel::after {
  bottom: -1px; right: -1px;
  border-bottom: 2px solid var(--theme-accent);
  border-right: 2px solid var(--theme-accent);
  filter: drop-shadow(0 0 6px var(--theme-glow-outer));
}
.db-header {
  border-bottom-color: var(--theme-accent-edge) !important;
}
.db-title {
  color: color-mix(in srgb, var(--theme-accent) 35%, #f5fbff) !important;
  text-shadow: 0 0 10px var(--theme-glow-outer), 0 0 24px var(--theme-glow-inner) !important;
  letter-spacing: 8px !important;
}

/* ============================================================
   STATS REVAMP — simpler, themed. Collapse heavy prose into a
   quick summary row; everything else inherits the themed panel
   chrome.
   ============================================================ */
.stats-summary-chip {
  border-color: var(--theme-accent-edge) !important;
  box-shadow: 0 0 10px var(--theme-glow-inner), inset 0 0 0 1px var(--theme-wash-08) !important;
}
.stats-summary-label {
  color: color-mix(in srgb, var(--theme-accent) 35%, #cfe9fb) !important;
}
.stats-summary-value {
  color: color-mix(in srgb, var(--theme-accent) 30%, white) !important;
  text-shadow: 0 0 6px var(--theme-glow-outer) !important;
}
/* Hide the wordy definition prose — the chips convey the key
   numbers; tooltips still surface the detail on hover for anyone
   who wants the full methodology. */
.stats-def-body,
.stats-legend-body,
.stats-methodology {
  display: none !important;
}

/* ============================================================
   MY DECKS — themed cards + New Deck button picks up accent
   instead of the fixed green.
   ============================================================ */
.md-deck-card {
  border-color: var(--theme-accent-edge) !important;
  background: linear-gradient(180deg, var(--theme-wash-05) 0%, rgba(0,0,0,0) 45%), #060a12 !important;
  box-shadow: 0 0 10px var(--theme-glow-inner), inset 0 0 0 1px var(--theme-wash-08) !important;
}
.md-deck-card:hover {
  border-color: var(--theme-accent-bright) !important;
  box-shadow: 0 0 16px var(--theme-glow-outer), 0 0 30px var(--theme-glow-inner) !important;
}
.md-deck-name {
  color: color-mix(in srgb, var(--theme-accent) 40%, #f5fbff) !important;
  text-shadow: 0 0 6px var(--theme-glow-inner) !important;
}
.md-new-btn {
  border-color: var(--theme-accent-bright) !important;
  color: color-mix(in srgb, var(--theme-accent) 45%, white) !important;
  box-shadow: 0 0 10px var(--theme-glow-inner) !important;
}
.md-new-btn:hover {
  color: #f5fbff !important;
  box-shadow: 0 0 14px var(--theme-glow-outer), 0 0 28px var(--theme-glow-inner) !important;
}
.md-title {
  color: color-mix(in srgb, var(--theme-accent) 35%, #f5fbff) !important;
  text-shadow: 0 0 10px var(--theme-glow-outer), 0 0 24px var(--theme-glow-inner) !important;
}
.md-subtitle,
.stats-subtitle {
  color: color-mix(in srgb, var(--theme-accent) 40%, #cfe9fb) !important;
  text-shadow: 0 0 6px var(--theme-glow-inner) !important;
}
.stats-title {
  color: color-mix(in srgb, var(--theme-accent) 35%, #f5fbff) !important;
  text-shadow: 0 0 10px var(--theme-glow-outer), 0 0 24px var(--theme-glow-inner) !important;
}

/* ============================================================
   FULL-CONNECTED THEME PASS — every neon surface tracks the
   same "current" so the whole game reads as one Tron circuit:
   the colour you pick in Settings flows through UI chrome,
   HUD pill, draft phase, player health bar, block meter, dead
   pile, card names/highlights on your side, and the lane
   centerlines leading up from your banner. Enemy mirrors
   symmetrically via --enemy-*. Contested lane middle is a
   colour-mix of both sides so when two different themes meet
   you get a real blend (red + gold → orange).
   ============================================================ */

/* ---- Board card name + desc highlights follow side theme ---- */
.card.ally-card .card-name {
  color: color-mix(in srgb, var(--player-accent) 35%, white) !important;
  text-shadow:
    0 0 4px var(--player-accent-bright),
    0 0 12px var(--player-glow-outer),
    0 0 20px var(--player-glow-inner),
    0 1px 2px rgba(0,0,0,0.95) !important;
}
.card.enemy-card .card-name {
  color: color-mix(in srgb, rgb(var(--enemy-r), var(--enemy-g), var(--enemy-b)) 35%, white) !important;
  text-shadow:
    0 0 4px var(--enemy-accent-bright),
    0 0 12px var(--enemy-glow-outer),
    0 0 20px var(--enemy-glow-inner),
    0 1px 2px rgba(0,0,0,0.95) !important;
}
/* "WHEN PLAYED:" / "START OF TRICKS:" trigger labels. Keep them in
   the full faction/rarity color via --portrait-frame-rgb instead of
   mixing with white — user direction: "all the text be that one
   color". The side-glow text-shadow stays so the label still anchors
   visually against the painting. */
.card.ally-card .card-desc b {
  color: rgba(var(--portrait-frame-rgb, 79,195,247), 1) !important;
  text-shadow:
    0 0 4px var(--player-accent-bright),
    0 0 8px var(--player-glow-outer) !important;
}
.card.enemy-card .card-desc b {
  color: rgba(var(--portrait-frame-rgb, 231,76,60), 1) !important;
  text-shadow:
    0 0 4px var(--enemy-accent-bright),
    0 0 8px var(--enemy-glow-outer) !important;
}
/* Desc body halo — side glow */
.card.ally-card .card-desc {
  text-shadow:
    0 0 5px var(--player-glow-outer),
    0 0 10px var(--player-glow-inner) !important;
}
.card.enemy-card .card-desc {
  text-shadow:
    0 0 5px var(--enemy-glow-outer),
    0 0 10px var(--enemy-glow-inner) !important;
}

/* ---- Dead-pile badges follow side theme ---- */
.ai-bar .pile-badge.dead-pile,
.info-bar.ai-bar .pile-badge.dead-pile {
  color: color-mix(in srgb, rgb(var(--enemy-r), var(--enemy-g), var(--enemy-b)) 35%, white) !important;
  border-color: var(--enemy-accent-bright) !important;
  box-shadow: 0 0 8px var(--enemy-glow-outer), 0 0 16px var(--enemy-glow-inner) !important;
}
.ai-bar .pile-badge.dead-pile:hover,
.info-bar.ai-bar .pile-badge.dead-pile:hover {
  background: rgba(var(--enemy-r), var(--enemy-g), var(--enemy-b), 0.10) !important;
  border-color: var(--enemy-accent-bright) !important;
  box-shadow: 0 0 12px var(--enemy-glow-outer), inset 0 0 10px var(--enemy-glow-inner) !important;
}
.player-bar .pile-badge.dead-pile {
  color: color-mix(in srgb, var(--player-accent) 35%, white) !important;
  border-color: var(--player-accent-bright) !important;
  box-shadow: 0 0 8px var(--player-glow-outer), 0 0 16px var(--player-glow-inner) !important;
}
.player-bar .pile-badge.dead-pile:hover {
  background: rgba(var(--player-r), var(--player-g), var(--player-b), 0.10) !important;
  border-color: var(--player-accent-bright) !important;
  box-shadow: 0 0 12px var(--player-glow-outer), inset 0 0 10px var(--player-glow-inner) !important;
}

/* ---- Block meter value text follows side theme ---- */
.player-bar .block-circle-value {
  color: color-mix(in srgb, var(--player-accent) 35%, white) !important;
  text-shadow: 0 0 6px var(--player-glow-outer) !important;
}
.ai-bar .block-circle-value {
  color: color-mix(in srgb, rgb(var(--enemy-r), var(--enemy-g), var(--enemy-b)) 35%, white) !important;
  text-shadow: 0 0 6px var(--enemy-glow-outer) !important;
}

/* ---- HUD pill content follows theme ---- */
.hud-phase,
body.turn-player .hud-phase,
body.turn-ai .hud-phase {
  color: color-mix(in srgb, var(--theme-accent) 35%, #f5fbff) !important;
  text-shadow: 0 0 6px var(--theme-glow-outer), 0 0 12px var(--theme-glow-inner) !important;
}
/* Round badge — DEFAULT (no firstPlayer set yet) follows theme.
   Round-first-player / round-first-ai overrides paint side-specific
   neon (green = player, red = AI) so the diamond always signals
   initiative at a glance. User spec: "this needs to be neon
   highlighted depending on who goes first." */
.hud-round {
  color: color-mix(in srgb, var(--theme-accent) 40%, white) !important;
  text-shadow: 0 0 6px var(--theme-glow-outer) !important;
}
.hud-round #round-num {
  /* No box-shadow on the parent — it's a 22x22 SQUARE so any halo
     here paints a square ghost behind the diamond. The diamond's
     glow lives on the rotated ::before which IS diamond-shaped.
     User feedback: "It's pulsing, but you can see the square clearly
     behind it. I want that square gone." */
  box-shadow: none !important;
  color: color-mix(in srgb, var(--theme-accent) 30%, white) !important;
  text-shadow: 0 0 6px var(--theme-accent-bright), 0 0 12px var(--theme-glow-outer) !important;
}
/* Player goes first — green neon, matching the player HUD bar tint.
   The diamond shape is the `::before` pseudo of #round-num, so the
   border-color + box-shadow have to be overridden THERE (not on the
   parent) to actually repaint the ring. */
/* Round-first overrides: previously hardcoded green (player-first) and
   red (ai-first) regardless of the user's chosen Neon Theme. User
   report: "in white preview the round is green for some reason."
   Now driven by the same --player-r/g/b / --enemy-r/g/b triplets the
   rest of the chrome uses; each body.theme-* class redefines those so
   the ROUND pill recolors with the picked theme. !important kept to
   beat the catch-all base rule lower in the file. */
body.round-first-player .hud-round {
  color: rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 1) !important;
  text-shadow: 0 0 6px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.55) !important;
}
body.round-first-player .hud-round #round-num {
  color: rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 1) !important;
  text-shadow:
    0 0 6px  rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 1),
    0 0 14px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.55) !important;
}
body.round-first-player .hud-round #round-num::before {
  border-color: rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 1) !important;
  box-shadow:
    inset 0 0 0 1px rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.30),
    0 0 10px        rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.85),
    0 0 22px        rgba(var(--player-r, 79), var(--player-g, 195), var(--player-b, 247), 0.45) !important;
}
/* AI goes first — enemy color, theme-aware. */
body.round-first-ai .hud-round {
  color: rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 1) !important;
  text-shadow: 0 0 6px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.55) !important;
}
body.round-first-ai .hud-round #round-num {
  color: rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 1) !important;
  text-shadow:
    0 0 6px  rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 1),
    0 0 14px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.55) !important;
}
body.round-first-ai .hud-round #round-num::before {
  border-color: rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 1) !important;
  box-shadow:
    inset 0 0 0 1px rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.30),
    0 0 10px        rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.85),
    0 0 22px        rgba(var(--enemy-r, 231), var(--enemy-g, 76), var(--enemy-b, 60), 0.45) !important;
}
/* Deck + Tricks counters both follow theme now — user wants every HUD
   segment connected to the picked neon. Tricks card-body still purple. */
.hud-pill-main {
  border-color: var(--theme-accent-bright) !important;
  box-shadow: 0 0 7px var(--theme-glow-outer), 0 0 14px var(--theme-glow-inner) !important;
}
body.round-first-player .hud-pill-main,
body.round-first-ai .hud-pill-main {
  border-color: var(--theme-accent-bright) !important;
  box-shadow: 0 0 7px var(--theme-glow-outer), 0 0 14px var(--theme-glow-inner) !important;
}
.hud-count-deck {
  color: color-mix(in srgb, var(--theme-accent) 35%, #cfe9fb) !important;
}
.hud-count-deck b {
  color: color-mix(in srgb, var(--theme-accent) 30%, white) !important;
  border-color: var(--theme-accent-bright) !important;
  box-shadow:
    0 0 5px var(--theme-glow-outer),
    0 0 10px var(--theme-glow-inner),
    inset 0 0 5px var(--theme-wash-08) !important;
  text-shadow: 0 0 6px var(--theme-accent-bright), 0 0 10px var(--theme-glow-outer) !important;
}
.hud-count-tricks {
  color: color-mix(in srgb, var(--theme-accent) 35%, #cfe9fb) !important;
}
.hud-count-tricks b {
  color: color-mix(in srgb, var(--theme-accent) 30%, white) !important;
  border-color: var(--theme-accent-bright) !important;
  box-shadow:
    0 0 5px var(--theme-glow-outer),
    0 0 10px var(--theme-glow-inner),
    inset 0 0 5px var(--theme-wash-08) !important;
  text-shadow: 0 0 6px var(--theme-accent-bright), 0 0 10px var(--theme-glow-outer) !important;
}

/* ============================================================
   DRAFT PANEL CHROME — every white surface becomes theme for
   the card draft; trick draft keeps its purple per prior rule.
   ============================================================ */
.draft-panel:not(.draft-tricks) {
  border-top-color: var(--theme-accent-bright) !important;
  border-bottom-color: var(--theme-accent-bright) !important;
  box-shadow:
    0 -12px 14px -12px var(--theme-glow-outer),
    0  12px 14px -12px var(--theme-glow-outer) !important;
  background:
    radial-gradient(ellipse at top, var(--theme-wash-05) 0%, rgba(255,255,255,0) 60%),
    #000 !important;
}
.draft-panel:not(.draft-tricks) .draft-hud-label {
  color: color-mix(in srgb, var(--theme-accent) 25%, white) !important;
  text-shadow:
    0 0 8px var(--theme-accent-bright),
    0 0 18px var(--theme-glow-outer),
    0 0 28px var(--theme-glow-inner) !important;
}
.draft-panel:not(.draft-tricks) .draft-hud-sub {
  color: color-mix(in srgb, var(--theme-accent) 30%, white) !important;
  text-shadow:
    0 0 6px var(--theme-accent-bright),
    0 0 14px var(--theme-glow-outer) !important;
}
.draft-panel:not(.draft-tricks) .draft-hud-row {
  border-bottom-color: var(--theme-accent-edge) !important;
}
/* Progress pips */
.draft-panel:not(.draft-tricks) .draft-pip {
  border-color: var(--theme-accent-edge) !important;
  box-shadow: inset 0 0 4px var(--theme-glow-inner) !important;
}
.draft-panel:not(.draft-tricks) .draft-pip.pip-done {
  background: var(--theme-accent) !important;
  border-color: var(--theme-accent-bright) !important;
  box-shadow: 0 0 8px var(--theme-glow-outer), 0 0 14px var(--theme-glow-inner) !important;
}
.draft-panel:not(.draft-tricks) .draft-pip.pip-current {
