/* General HUD divider (not the cyan-specific one). */
.hud-divider:not(.hud-divider-cyan) {
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(var(--theme-rgb, 79,195,247), 0.55) 30%,
    rgba(var(--theme-rgb, 79,195,247), 0.55) 70%,
    transparent 100%) !important;
}
.hud-divider:not(.hud-divider-cyan)::after {
  background: rgb(var(--theme-rgb, 79,195,247)) !important;
  box-shadow:
    0 0 6px rgba(var(--theme-rgb, 79,195,247), 1),
    0 0 14px rgba(var(--theme-rgb, 79,195,247), 0.65) !important;
